(() => {
  const KEY = "quietStrengthRecovery.v02";
  const OLD_KEY = "quietStrengthRecovery.v01";
  const SECURE_KEY = "quietStrengthRecovery.secure.v1";
  const AUTH_KEY = "quietStrengthRecovery.auth.v1";
  const AUTH_SESSION_KEY = "quietStrengthRecovery.auth.session";
  const todayISO = () => {
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth()+1).padStart(2,'0');
    const day = String(d.getDate()).padStart(2,'0');
    return `${y}-${m}-${day}`;
  };

  const isStandalone = () => window.matchMedia?.('(display-mode: standalone)').matches || window.navigator.standalone === true;
  const isIOS = () => /iphone|ipad|ipod/i.test(navigator.userAgent || '');
  function installPanel(){
    if(isStandalone()) return `<div class="client-ready"><div class="client-ready-icon">✓</div><div><strong>Installed on this device</strong><p>Quiet Strength can be opened from your Home Screen or app list and continues to work offline after the first successful load.</p></div></div>`;
    if(isIOS()) return `<div class="install-panel"><div><div class="eyebrow">Optional — install on iPhone / iPad</div><h3>Keep Quiet Strength Recovery on your Home Screen</h3><p>You can use it in Safari now. To install it, tap the <strong>Share</strong> button, choose <strong>Add to Home Screen</strong>, then tap <strong>Add</strong>.</p></div><div class="install-steps"><span>1. Share</span><span>2. Add to Home Screen</span><span>3. Add</span></div></div>`;
    return `<div class="install-panel"><div><div class="eyebrow">Optional — install this workbook</div><h3>Keep Quiet Strength Recovery on this device</h3><p>You can use it in your browser now. If your browser supports direct installation, use the button below. Once loaded successfully, the workbook is also prepared for offline use.</p></div><div class="toolbar"><button class="btn" id="clientInstallBtn" type="button" ${window._qsInstallPrompt?'':'disabled'}>${window._qsInstallPrompt?'Install Quiet Strength Recovery':'Install from browser menu'}</button></div></div>`;
  }

  const defaults = {
    checkins:{}, dailyOutputs:{}, dailyUsage:{}, recovery:{startDate:"",displayName:""},
    brave:{break:"",recognise:"",accountability:"",view:"",execute:""}, urges:{body:"",underneath:"",space:"",connect:"",choose:""},
    feelings:{primary:"",secondary:"",where:"",support:""}, balance:{recovery:5,sleep:5,work:5,family:5,health:5,connection:5,service:5,enjoyment:5},
    support:{trusted:"",peers:"",family:"",professional:"",medical:"",groups:"",places:"",activities:""}, warning:{green:"",amber:"",red:""},
    pages:{}, notes:{}, meta:{recentTools:[], lastOpened:"", savedAt:""}, settings:{localOnly:true,textSize:"normal",highContrast:false}
  };
  const clone = x => JSON.parse(JSON.stringify(x));
  const isRecord=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
  const isISODate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;
  const deepMerge = (target, source) => {const out={...target};if(!isRecord(source))return out;for(const [k,v] of Object.entries(source)){if(k==='__proto__'||k==='constructor'||k==='prototype')continue;if(isRecord(v))out[k]=deepMerge(isRecord(target?.[k])?target[k]:{},v);else out[k]=v}return out};
  const validBackup=x=>isRecord(x)&&['checkins','dailyOutputs','dailyUsage','recovery','brave','urges','feelings','balance','support','warning','pages','notes','meta','settings'].every(k=>x[k]===undefined||isRecord(x[k]))&&Object.entries(x.checkins||{}).every(([date,day])=>isISODate(date)&&isRecord(day))&&Object.entries(x.dailyOutputs||{}).every(([date,out])=>isISODate(date)&&(isRecord(out)||Array.isArray(out)&&out.every(isRecord)))&&Object.entries(x.dailyUsage||{}).every(([date,used])=>isISODate(date)&&Array.isArray(used))&&(!x.meta?.recentTools||Array.isArray(x.meta.recentTools));
  function migrateOld(){
    try{
      const old=JSON.parse(localStorage.getItem(OLD_KEY)||"null"); if(!old) return {};
      const migrated={...old,checkins:{}};
      if(old.daily) migrated.checkins[todayISO()] = old.daily;
      delete migrated.daily;
      return migrated;
    }catch{return {}}
  }
  function loadLegacy(){try{const v=localStorage.getItem(KEY);const parsed=v?JSON.parse(v):migrateOld();return validBackup(parsed)?parsed:{}}catch{return {}}}
  let state=deepMerge(clone(defaults),loadLegacy());
  const DB_NAME="quietStrengthRecoveryDB", DB_STORE="state";
  function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){resolve(null);return}const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(DB_STORE))r.result.createObjectStore(DB_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
  async function idbSave(payload){try{const db=await openDB();if(!db)return false;await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(clone(payload),'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();return true}catch{return false}}
  async function idbLoad(){try{const db=await openDB();if(!db)return null;const data=await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly');const q=tx.objectStore(DB_STORE).get('main');q.onsuccess=()=>resolve(q.result||null);q.onerror=()=>reject(q.error)});db.close();return data}catch{return null}}
  async function idbClear(){try{const db=await openDB();if(!db)return true;await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete('main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();return true}catch{return false}}
  function loadAuth(){try{return JSON.parse(localStorage.getItem(AUTH_KEY)||'null')}catch{return null}}
  let authMeta=loadAuth();
  let isUnlocked=false, dataKey=null;
  let authFailures=0, authBlockedUntil=0, inactivityTimer=null;
  const bytesToB64=bytes=>{const chunks=[];for(let i=0;i<bytes.length;i+=0x8000)chunks.push(String.fromCharCode(...bytes.subarray(i,i+0x8000)));return btoa(chunks.join(''));};
  const b64ToBytes=b64=>Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
  async function legacyPinDigest(pin,saltB64,iterations=180000){
    if(!window.crypto?.subtle) throw new Error('Secure passcode functions are not available in this browser.');
    const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);
    const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:b64ToBytes(saltB64),iterations},material,256);
    return bytesToB64(new Uint8Array(bits));
  }
  async function derivePinSecrets(pin,saltB64,iterations=600000){
    if(!window.crypto?.subtle) throw new Error('Secure encryption is not available in this browser.');
    const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);
    const bits=new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:b64ToBytes(saltB64),iterations},material,512));
    const verifier=bytesToB64(bits.slice(0,32));
    const key=await crypto.subtle.importKey('raw',bits.slice(32),{name:'AES-GCM'},false,['encrypt','decrypt']);
    return {verifier,key};
  }
  const constantTimeEqual=(a,b)=>{if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0};
  const isEncryptedEnvelope=x=>isRecord(x)&&x.format==='qsr-encrypted-state'&&x.version===1&&typeof x.iv==='string'&&typeof x.ciphertext==='string';
  async function encryptStatePayload(payload,key=dataKey){
    if(!key)throw new Error('Workbook encryption key is not available.');
    const iv=new Uint8Array(12);crypto.getRandomValues(iv);
    const plain=new TextEncoder().encode(JSON.stringify(payload));
    const cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain));
    return {format:'qsr-encrypted-state',version:1,alg:'AES-GCM',iv:bytesToB64(iv),ciphertext:bytesToB64(cipher),updatedAt:payload?.meta?.savedAt||new Date().toISOString()};
  }
  async function decryptStatePayload(envelope,key=dataKey){
    if(!isEncryptedEnvelope(envelope)||!key)throw new Error('Encrypted workbook data is not available.');
    const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(envelope.iv)},key,b64ToBytes(envelope.ciphertext));
    const parsed=JSON.parse(new TextDecoder().decode(plain));
    if(!validBackup(parsed))throw new Error('Decrypted workbook data failed validation.');
    return deepMerge(clone(defaults),parsed);
  }
  function loadLocalEnvelope(){try{const raw=localStorage.getItem(SECURE_KEY);const parsed=raw?JSON.parse(raw):null;return isEncryptedEnvelope(parsed)?parsed:null}catch{return null}}
  async function loadBestEncryptedEnvelope(){const local=loadLocalEnvelope();const fromIdb=await idbLoad();const idb=isEncryptedEnvelope(fromIdb)?fromIdb:null;if(!local)return idb;if(!idb)return local;return String(idb.updatedAt||'')>String(local.updatedAt||'')?idb:local}
  async function loadBestLegacyState(){let best=validBackup(state)?clone(state):{};const idb=await idbLoad();if(validBackup(idb)&&String(idb.meta?.savedAt||'')>String(best.meta?.savedAt||''))best=idb;return deepMerge(clone(defaults),best)}
  function clearLegacyPlaintextCopies(){try{localStorage.removeItem(KEY);localStorage.removeItem(OLD_KEY)}catch{}}
  const isEncryptedBackupPackage=x=>isRecord(x)&&x.format==='qsr-encrypted-backup'&&x.version===1&&isRecord(x.kdf)&&typeof x.kdf.salt==='string'&&typeof x.kdf.verifier==='string'&&Number.isFinite(Number(x.kdf.iterations))&&isEncryptedEnvelope(x.payload);
  async function createEncryptedBackupPackage(){if(!dataKey||!authMeta||authMeta.version<2)throw new Error('Unlock the workbook before exporting a backup.');const payload=await encryptStatePayload(clone(state),dataKey);return {format:'qsr-encrypted-backup',version:1,createdAt:new Date().toISOString(),kdf:{name:'PBKDF2-SHA256',salt:authMeta.salt,iterations:authMeta.iterations,verifier:authMeta.hash},payload}}
  async function decryptEncryptedBackupPackage(pkg,pin){if(!isEncryptedBackupPackage(pkg))throw new Error('Invalid encrypted backup.');const secrets=await derivePinSecrets(pin,pkg.kdf.salt,Number(pkg.kdf.iterations));if(!constantTimeEqual(secrets.verifier,pkg.kdf.verifier))throw new Error('Incorrect backup passcode.');return decryptStatePayload(pkg.payload,secrets.key)}
  function requestBackupPasscode(){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.setAttribute('style','position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,.72);display:grid;place-items:center;padding:20px');overlay.innerHTML='<div class="auth-card" style="max-width:520px;width:100%"><div class="eyebrow">Encrypted backup</div><h2>Enter the backup passcode</h2><p>Use the passcode that protected Quiet Strength when this backup was created.</p><form id="backupPasscodeForm"><div class="field"><label for="backupPasscodeInput">Passcode</label><input id="backupPasscodeInput" type="password" inputmode="numeric" pattern="[0-9]*" minlength="4" maxlength="8" autocomplete="current-password" required autofocus></div><div class="toolbar"><button class="btn auth-primary" type="submit">Unlock backup</button><button class="btn secondary" id="backupPasscodeCancel" type="button">Cancel</button></div></form></div>';document.body.appendChild(overlay);const done=value=>{overlay.remove();resolve(value)};overlay.querySelector('#backupPasscodeForm').addEventListener('submit',e=>{e.preventDefault();done(overlay.querySelector('#backupPasscodeInput').value)});overlay.querySelector('#backupPasscodeCancel').addEventListener('click',()=>done(null));overlay.querySelector('#backupPasscodeInput').focus()})}
  function authMinutes(){return Math.max(1,Number(authMeta?.autolockMinutes||5))}
  function saveAuth(){if(authMeta)localStorage.setItem(AUTH_KEY,JSON.stringify(authMeta));else localStorage.removeItem(AUTH_KEY)}
  async function createOrChangePasscode(pin,autolockMinutes=authMinutes(),allowLegacy=false){
    if(!(allowLegacy?/^\d{4,8}$/:/^\d{6,8}$/).test(pin)) throw new Error('Use a 6 to 8 digit passcode.');
    if(!window.crypto?.subtle)throw new Error('Secure encryption is not available in this browser.');
    const salt=new Uint8Array(16);crypto.getRandomValues(salt);
    const iterations=600000,saltB64=bytesToB64(salt),secrets=await derivePinSecrets(pin,saltB64,iterations);
    const previousAuth=authMeta,previousKey=dataKey;
    authMeta={version:2,salt:saltB64,hash:secrets.verifier,iterations,autolockMinutes:Number(autolockMinutes)||5,createdAt:previousAuth?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
    dataKey=secrets.key;saveAuth();isUnlocked=true;try{sessionStorage.setItem(AUTH_SESSION_KEY,'1')}catch{}authFailures=0;authBlockedUntil=0;
    const saved=await persist();if(!saved){authMeta=previousAuth;dataKey=previousKey;saveAuth();throw new Error('The encrypted workbook could not be saved on this device.');}
    armAutoLock();
  }
  async function verifyPasscode(pin){
    if(!authMeta)return false;
    if(Date.now()<authBlockedUntil) throw new Error('Too many attempts. Wait 30 seconds and try again.');
    let ok=false;
    if(Number(authMeta.version||1)>=2){
      const secrets=await derivePinSecrets(pin,authMeta.salt,Number(authMeta.iterations)||600000);ok=constantTimeEqual(secrets.verifier,authMeta.hash);
      if(ok){dataKey=secrets.key;const envelope=await loadBestEncryptedEnvelope();if(envelope)state=await decryptStatePayload(envelope,dataKey);else{state=await loadBestLegacyState();isUnlocked=true;await persist()}}
    }else{
      const digest=await legacyPinDigest(pin,authMeta.salt,Number(authMeta.iterations)||180000);ok=constantTimeEqual(digest,authMeta.hash);
      if(ok){state=await loadBestLegacyState();isUnlocked=true;await createOrChangePasscode(pin,authMinutes(),true);return true}
    }
    if(ok){isUnlocked=true;try{sessionStorage.setItem(AUTH_SESSION_KEY,'1')}catch{}authFailures=0;authBlockedUntil=0;armAutoLock();return true}
    dataKey=null;authFailures++;
    if(authFailures>=5){authFailures=0;authBlockedUntil=Date.now()+30000;throw new Error('Too many incorrect attempts. Quiet Strength Recovery is locked for 30 seconds.');}
    throw new Error(`Incorrect passcode. ${5-authFailures} attempt${5-authFailures===1?'':'s'} before a short lockout.`);
  }
  function armAutoLock(){if(!isUnlocked||!authMeta)return;clearTimeout(inactivityTimer);inactivityTimer=setTimeout(()=>lockApp(true),authMinutes()*60*1000)}
  async function lockApp(auto=false){if(!authMeta)return;await flushPendingSave();dataKey=null;isUnlocked=false;try{sessionStorage.removeItem(AUTH_SESSION_KEY)}catch{}clearTimeout(inactivityTimer);render();if(auto)document.querySelector('#authMessage')?.focus()}
  async function resetLockedDevice(){
    const first=confirm('Forgotten passcode? The passcode cannot be recovered. The only reset option is to erase all Quiet Strength data saved on this device. Continue?');
    if(!first)return;
    const second=confirm('Final warning: this permanently erases this device\'s workbook entries, daily archive, backups inside the app, and passcode. Export is not possible while locked. Erase everything?');
    if(!second)return;
    clearTimeout(saveTimer);await idbWriteQueue;if(!await idbClear()){alert('The device could not finish erasing stored data. Please try again before giving this device to anyone else.');return}try{localStorage.removeItem(KEY);localStorage.removeItem(OLD_KEY);localStorage.removeItem(SECURE_KEY);localStorage.removeItem(AUTH_KEY)}catch{alert('The device could not finish erasing stored data. Please try again before giving this device to anyone else.');return}try{sessionStorage.removeItem(AUTH_SESSION_KEY)}catch{}authMeta=null;dataKey=null;isUnlocked=false;state=clone(defaults);render();
  }
  const urgentCountryStorageKey='qsr_urgent_support_country_v1';
  const urgentCountries=[['uk','United Kingdom'],['ie','Ireland'],['us','United States'],['ca','Canada'],['au','Australia'],['nz','New Zealand'],['other','Another country']];
  function selectedUrgentCountry(){try{const saved=localStorage.getItem(urgentCountryStorageKey);return urgentCountries.some(([code])=>code===saved)?saved:'uk'}catch{return 'uk'}}
  function urgentCountryResources(country){
    switch(country){
      case 'uk': return '<div class="urgent-country-panel"><h3>United Kingdom</h3><p>If there is immediate danger, an overdose, or severe withdrawal, call emergency services now.</p><div class="urgent-actions"><a class="btn emergency-btn" href="tel:999">Call 999</a><a class="btn emergency-btn" href="tel:112">Call 112</a></div><h3>Urgent mental health support in England</h3><p>Call NHS 111 and choose the mental health option for urgent, non-emergency help. This NHS 111 route is for England. If you are elsewhere in the UK, use your local urgent mental health service.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:111">Call NHS 111</a><a class="btn urgent-secondary" href="tel:116123">Call Samaritans 116 123</a></div><p class="urgent-links"><a href="https://www.nhs.uk/nhs-services/mental-health-services/">NHS urgent mental health support</a> · <a href="https://www.samaritans.org/how-we-can-help/contact-samaritan/">Contact Samaritans</a></p></div>';
      case 'ie': return '<div class="urgent-country-panel"><h3>Ireland</h3><p>If there is immediate danger, an overdose, or severe withdrawal, call emergency services.</p><div class="urgent-actions"><a class="btn emergency-btn" href="tel:112">Call 112</a><a class="btn emergency-btn" href="tel:999">Call 999</a></div><h3>Alcohol and drug support</h3><p>The HSE Drugs and Alcohol Helpline offers confidential information, support and referral.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:1800459459">Call 1800 459 459</a></div><p>Monday to Friday, 9:30am to 5:30pm.</p><h3>Someone to talk to</h3><p>Samaritans offers free listening support any time, day or night.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:116123">Call Samaritans 116 123</a><a class="btn urgent-secondary" href="sms:50808?body=HELLO">Text HELLO to 50808</a></div><p>Text About It is a free, 24/7 support service. Text HELLO to 50808.</p><p class="urgent-links"><a href="https://www2.hse.ie/services/habit-addiction/drugs-and-alcohol-helpline/">HSE Drugs and Alcohol Helpline</a> · <a href="https://www2.hse.ie/mental-health/services-support/get-urgent-help/">HSE urgent mental health support</a> · <a href="https://www.samaritans.org/samaritans-ireland/about/governance-and-structure/contact-us/">Samaritans Ireland</a></p></div>';
      case 'us': return '<div class="urgent-country-panel"><h3>United States</h3><p>For immediate danger, overdose, or severe withdrawal, call emergency services.</p><div class="urgent-actions"><a class="btn emergency-btn" href="tel:911">Call 911</a></div><p>If you are in emotional distress or thinking about suicide, call or text 988 for crisis support.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:988">Call 988</a><a class="btn urgent-secondary" href="sms:988">Text 988</a></div><p>For free, confidential information and treatment referrals for mental health or substance use, call SAMHSA’s National Helpline.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:18006624357">Call 1-800-662-HELP</a></div><p class="urgent-links"><a href="https://988lifeline.org/">988 Suicide &amp; Crisis Lifeline</a> · <a href="https://www.samhsa.gov/find-help/helplines/national-helpline">SAMHSA National Helpline</a> · <a href="https://findtreatment.gov/">FindTreatment.gov</a></p></div>';
      case 'ca': return '<div class="urgent-country-panel"><h3>Canada</h3><p>For immediate danger, overdose, or severe withdrawal, call emergency services.</p><div class="urgent-actions"><a class="btn emergency-btn" href="tel:911">Call 911</a></div><p>If you are thinking about suicide, or worried about someone else, call or text 9-8-8 for crisis support.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:988">Call 9-8-8</a><a class="btn urgent-secondary" href="sms:988">Text 9-8-8</a></div><p>For substance-use services, see the Government of Canada directory of Canada-wide and provincial or territorial supports.</p><p class="urgent-links"><a href="https://988.ca/">9-8-8 Suicide Crisis Helpline</a> · <a href="https://www.canada.ca/en/health-canada/services/substance-use/get-help-with-substance-use.html">Canada substance-use support directory</a></p></div>';
      case 'au': return '<div class="urgent-country-panel"><h3>Australia</h3><p>For immediate danger, overdose, or severe withdrawal, call emergency services.</p><div class="urgent-actions"><a class="btn emergency-btn" href="tel:000">Call 000</a></div><p>For alcohol or other drug support, contact the National Alcohol and Other Drug Hotline. It connects callers to services in their state or territory; check the official page for local details.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:1800250015">Call 1800 250 015</a></div><p>For personal crisis support, call Lifeline.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:131114">Call Lifeline 13 11 14</a></div><p class="urgent-links"><a href="https://www.health.gov.au/contacts/national-alcohol-and-other-drug-hotline">Australian Government alcohol and drug hotline</a> · <a href="https://www.healthdirect.gov.au/mental-health-crisis-support">Healthdirect mental health crisis support</a></p></div>';
      case 'nz': return '<div class="urgent-country-panel"><h3>New Zealand</h3><p>For immediate danger, overdose, or severe withdrawal, call emergency services.</p><div class="urgent-actions"><a class="btn emergency-btn" href="tel:111">Call 111</a></div><p>For alcohol or other drug support, call the Alcohol Drug Helpline or text 8681.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:0800787797">Call 0800 787 797</a><a class="btn urgent-secondary" href="sms:8681">Text 8681</a></div><p>For brief emotional support, call or text 1737.</p><div class="urgent-actions"><a class="btn urgent-secondary" href="tel:1737">Call 1737</a><a class="btn urgent-secondary" href="sms:1737">Text 1737</a></div><p class="urgent-links"><a href="https://www.healthnz.govt.nz/health-topics/mental-health/where-to-get-help">Health New Zealand support options</a> · <a href="https://www.1737.org.nz/">1737 support</a></p></div>';
      default: return '<div class="urgent-country-panel"><h3>Another country</h3><p>Emergency numbers and crisis services differ by location. If someone is in immediate danger, has overdosed, or may be experiencing severe withdrawal, contact local emergency services or go to the nearest emergency department.</p><p>For non-emergency recovery or mental health support, contact a local health service, doctor, or recognized support organization in your area.</p></div>';
    }
  }
  function urgentSupportContent(){
    const selected=selectedUrgentCountry();
    return '<section class="urgent-support safety" aria-labelledby="urgentSupportTitle"><div class="eyebrow">Support in a crisis</div><h2 id="urgentSupportTitle">Need urgent help?</h2><p>If there is immediate danger, an overdose, or severe withdrawal, contact emergency services where you are now.</p><p>Severe alcohol withdrawal can include seizures, severe shaking, hallucinations, or confusion. If you may be dependent on alcohol, get medical advice before stopping suddenly.</p><div class="urgent-country-field"><label for="urgentCountrySelect">Choose the country where you are now</label><select id="urgentCountrySelect" aria-controls="urgentCountryResources">'+urgentCountries.map(([code,label])=>'<option value="'+code+'"'+(code===selected?' selected':'')+'>'+label+'</option>').join('')+'</select></div><div id="urgentCountryResources" class="urgent-country-resources" role="region" aria-live="polite">'+urgentCountryResources(selected)+'</div><p class="urgent-small">Service access and hours can vary by area. Quiet Strength is a workbook, not an emergency service.</p></section>';
  }
  document.addEventListener('change',function(event){
    const select=event.target;
    if(!select||select.id!=='urgentCountrySelect')return;
    const country=urgentCountries.some(([code])=>code===select.value)?select.value:'other';
    try{localStorage.setItem(urgentCountryStorageKey,country)}catch{}
    const panel=document.getElementById('urgentCountryResources');
    if(panel)panel.innerHTML=urgentCountryResources(country);
  });
  function urgentScreen(){return `<main class="urgent-screen"><a class="urgent-back" href="#home">← Back to Quiet Strength</a><div class="urgent-screen-card"><div class="eyebrow">Quiet Strength Recovery</div><h1>Support now</h1>${urgentSupportContent()}</div></main>`}
  function passcodeSetupScreen(){return `<div class="auth-shell"><div class="auth-card client-auth"><div class="auth-mark"><img src="assets/icon.svg" alt="Quiet Strength Recovery logo"></div><div class="eyebrow">Quiet Strength Recovery</div><h1>Your recovery space</h1><p>Free tools for adults aged 18+ in recovery. I share what helped me. You choose what helps you.</p><div class="notice">Your writing is encrypted on this device. No account, subscription or cloud journal is required.</div><p><a href="#urgent">Need support now?</a> · <a href="privacy-policy.html" target="_blank" rel="noopener">Privacy</a></p><h2>Create a passcode</h2><p>Use 6 to 8 digits you can remember. If you forget them, the app cannot recover your writing without your own backup.</p><form id="setupPasscodeForm"><div class="field"><label for="setupPin">New passcode</label><input id="setupPin" type="password" inputmode="numeric" pattern="[0-9]*" minlength="6" maxlength="8" autocomplete="new-password" required></div><div class="field"><label for="setupPin2">Confirm passcode</label><input id="setupPin2" type="password" inputmode="numeric" pattern="[0-9]*" minlength="6" maxlength="8" autocomplete="new-password" required></div><button class="btn auth-primary" type="submit">Create passcode & start</button><p class="auth-error" id="authMessage" tabindex="-1" role="alert" aria-live="assertive"></p></form><details class="auth-details"><summary>Before you start: support and privacy</summary><div class="notice"><strong>Disclaimer:</strong> Quiet Strength Recovery is a peer-support and educational recovery guide created from lived experience. It is not a medical device and does not diagnose, treat, cure or prevent any medical condition or mental health disorder. The information and tools provided are not a substitute for professional medical advice, clinical therapy or emergency medical intervention. Always consult a qualified healthcare professional for medical advice, diagnosis or treatment. If you or someone else is in immediate danger or crisis, contact local emergency services or a crisis helpline.</div><p>Use what helps and leave what does not. The core tools can reopen offline after an initial successful load. Browsers can remove stored data, so use Settings to export an encrypted backup and keep its passcode safe.</p><p>Individual text and PDF exports are readable files. Store them privately. The apps do not monitor your writing or alert anyone when you need help.</p><p><a href="downloads/Quiet-Strength-Recovery-v1.9.apk" download>Download the Android app</a></p></details></div></div>`}
  function preAuthPrivacyScreen(){return `<div class="auth-shell"><div class="auth-card client-auth"><div class="auth-mark"><img src="assets/icon.svg" alt="Quiet Strength Recovery logo"></div><div class="eyebrow">Privacy in plain English</div><h1>Your writing stays on this device</h1><div class="privacy-list"><div><strong>No account or subscription</strong><span>The complete recovery guide is free. This version has no Quiet Strength account or cloud sync.</span></div><div><strong>Encrypted local storage</strong><span>Your workbook entries are encrypted before they are stored in this browser/app on this device.</span></div><div><strong>Passcode</strong><span>Your passcode is used to derive the key that unlocks the encrypted workbook. Quiet Strength does not store the passcode itself.</span></div><div><strong>Encrypted backups</strong><span>Full backups created in Settings are encrypted and require the passcode that protected the workbook when that backup was made.</span></div><div><strong>Readable exports</strong><span>If you deliberately download or print an individual daily record, text archive or PDF, that file is readable. Store those exports privately.</span></div><div><strong>Website connection</strong><span>The website files are downloaded from the hosting service. Your typed workbook answers are not intentionally sent to Quiet Strength by this version.</span></div></div><p><a href="#urgent">Need urgent help?</a></p><button class="btn" id="privacyBackToSetup" type="button">Back to setup</button></div></div>`}
  function lockScreen(){return `<div class="auth-shell"><div class="auth-card"><div class="auth-mark locked"><img src="assets/icon.svg" alt="Quiet Strength Recovery logo"></div><div class="eyebrow">Device passcode</div><h1>Quiet Strength Recovery is locked</h1><p>Enter your passcode to continue.</p><form id="unlockForm"><div class="field"><label for="unlockPin">Passcode</label><input id="unlockPin" type="password" inputmode="numeric" pattern="[0-9]*" minlength="4" maxlength="8" autocomplete="current-password" autofocus required></div><button class="btn auth-primary" type="submit">Unlock</button><p class="auth-error" id="authMessage" tabindex="-1" role="alert" aria-live="assertive"></p></form><p><a href="#urgent">Need urgent help?</a></p><button class="link-button" id="forgotPasscodeBtn" type="button">Forgot passcode?</button><div class="auth-note">For privacy, Quiet Strength cannot reveal or recover the passcode. A forgotten passcode can only be reset by erasing this device's local workbook data.</div></div></div>`}
  function bindAuth(){
    const setup=document.querySelector('#setupPasscodeForm');if(setup)setup.addEventListener('submit',async e=>{e.preventDefault();const m=document.querySelector('#authMessage'),a=document.querySelector('#setupPin').value,b=document.querySelector('#setupPin2').value;m.textContent='';if(a!==b){m.textContent='The two passcodes do not match.';return}try{await createOrChangePasscode(a,5);render()}catch(err){m.textContent=err.message||'Passcode could not be created.'}});
    const unlock=document.querySelector('#unlockForm');if(unlock)unlock.addEventListener('submit',async e=>{e.preventDefault();const m=document.querySelector('#authMessage'),pin=document.querySelector('#unlockPin').value;m.textContent='';try{await verifyPasscode(pin);render()}catch(err){m.textContent=err.message||'Could not unlock Quiet Strength.';document.querySelector('#unlockPin').value='';document.querySelector('#unlockPin').focus()}});
    const forgot=document.querySelector('#forgotPasscodeBtn');if(forgot)forgot.addEventListener('click',resetLockedDevice);
    const privacyLink=document.querySelector('#preAuthPrivacyLink');if(privacyLink)privacyLink.addEventListener('click',e=>{e.preventDefault();location.hash='#privacy';render()});
    const privacyBack=document.querySelector('#privacyBackToSetup');if(privacyBack)privacyBack.addEventListener('click',()=>{location.hash='#home';render()});

  }
  let saveFailed=false,saveSequence=0,idbWriteQueue=Promise.resolve(),filePickerActive=false;
  function persist(){if(!isUnlocked||!dataKey||!authMeta)return Promise.resolve(false);state.meta.savedAt=new Date().toISOString();const snapshot=clone(state),sequence=++saveSequence;const run=async()=>{const envelope=await encryptStatePayload(snapshot,dataKey);let localSaved=false;try{localStorage.setItem(SECURE_KEY,JSON.stringify(envelope));localSaved=true}catch{}const idbSaved=await idbSave(envelope);const saved=localSaved||idbSaved;if(saved)clearLegacyPlaintextCopies();return saved};const write=idbWriteQueue.then(run,run);idbWriteQueue=write.catch(()=>false);return write.then(saved=>{if(sequence===saveSequence){saveFailed=!saved;if(saveFailed){updateStatus()}else flashSaved()}return saved}).catch(()=>{if(sequence===saveSequence){saveFailed=true;updateStatus()}return false})}
  let saveTimer; function queueSave(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,180)}
  function flashSaved(){const e=document.querySelector('#saveStatus');if(!e)return;e.innerHTML='<span class="status-dot"></span>Saved on this device';setTimeout(updateStatus,1200)}
  function updateStatus(){const e=document.querySelector('#saveStatus');if(!e)return;e.classList.toggle('save-warning',saveFailed);e.setAttribute('role',saveFailed?'alert':'status');if(saveFailed){e.textContent='Not saved. Keep this page open and export a backup from Settings.';return}e.innerHTML=`<span class="status-dot"></span>${navigator.onLine?'Device only • online':'Device only • offline'}`}
  function formatDay(date){try{return new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(date+'T12:00:00'))}catch{return date}}
  function formatWhen(iso){try{return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(iso))}catch{return iso||''}}
  function latestOutput(date){const x=state.dailyOutputs?.[date];if(!x)return null;return Array.isArray(x)?x[x.length-1]:x}
  function outputVersions(date){const x=state.dailyOutputs?.[date];if(!x)return [];return Array.isArray(x)?x:[x]}
  function applyAccessibility(){document.documentElement.dataset.textsize=state.settings.textSize||'normal';document.documentElement.classList.toggle('high-contrast',!!state.settings.highContrast)}
  function completeDay(date){const d=state.checkins?.[date];if(!d)return;const versions=outputVersions(date);const out={version:versions.length+1,completedAt:new Date().toISOString(),date,checkin:clone(d),toolsUsed:clone(state.dailyUsage?.[date]||[])};state.dailyOutputs[date]=[...versions,out];persist();location.hash='#day/'+date}
  function dayText(date,out){const d=out?.checkin||{};const flags=Object.entries(d.flags||{}).filter(([,v])=>v).map(([k])=>'• '+k).join('\n')||'None selected';const tools=(out?.toolsUsed||[]).map(id=>names[id]||id).join(', ')||'None recorded';return `QUIET STRENGTH RECOVERY\nDAILY RECOVERY OUTPUT\n\n${formatDay(date)}\nCompleted: ${formatWhen(out?.completedAt)}\n\nMORNING FEELING\n${d.feeling||'—'}\n\nJUST FOR TODAY\n${d.today||'—'}\n\nGRATITUDE\n1. ${d.g1||'—'}\n2. ${d.g2||'—'}\n3. ${d.g3||'—'}\n\nWHAT SHOWED UP\n${flags}\n\nWHAT WENT WELL\n${d.wentWell||'—'}\n\nWHAT WAS DIFFICULT / WHAT I LEARNED\n${d.learn||'—'}\n\nONE THING I CAN CARRY INTO TOMORROW\n${d.tomorrow||'—'}\n\nTOOLS USED THAT DAY\n${tools}\n\nThis output is a record of the person's own entries. It is not a score, diagnosis or clinical assessment.`}
  const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
  const hashParts=()=>{const raw=(location.hash||'#home').slice(1);const p=raw.split('/'),candidate=p.slice(1).join('/')||'';return {view:p[0]||'home',param:isISODate(candidate)?candidate:'',invalidParam:!!candidate&&!isISODate(candidate)}};
  const view=()=>hashParts().view;

  const names={
    daily:'Daily Check-In',feelings:'Feelings',urges:'Urges & Cravings',brave:'BRAVE',balance:'Recovery Balance',support:'Support Map',warning:'Warning Signs',
    rhythm:'Daily Recovery Rhythm',moment:'Moment Before the Action',consequences:'Consequences',fear:'Fear',perspective:'Perspective',familyPatterns:'Family Patterns',familyRoles:'Family Survival Roles',childhoodRules:'Childhood Rules',innerCritic:'Inner Critic',boundaries:'Boundaries',resentment:'Resentment',accountability:'Accountability',apologies:'Apologies & Repair',connection:'Connection & Isolation',working:'What Is Working?',rebuilding:'Rebuilding a Life',grounding:'Grounding & Stillness',values:'Values'
  };
  const interactiveIds=Object.keys(names);
  const catalog=[
    [2,'welcome','Welcome','A free, optional recovery guide based on lived experience.'],[3,'person','Person-Centred Recovery','Your way, not a rigid treatment programme.'],[4,'philosophy','Quiet Strength Philosophy','Recovery can be compassionate and still be honest.'],
    [5,'brave','The BRAVE Tool','Create a gap between the trigger and the next decision.'],[6,'moment','The Moment Before the Action','Map what happened — not to judge it, but to understand it.'],[7,'consequences','Consequences','Consequences are information, not punishment.'],[8,'rhythm','Daily Recovery Rhythm','Simple practices can make the day easier to see clearly.'],
    [9,'fear','Fear','Fear: fact or story?'],[10,'urges','Urges and Cravings','An urge is real. It is not an instruction.'],[11,'perspective','Perspective','Self-pity without self-attack: flip the negative.'],[12,'feelings','Feelings','Feelings are information, not instructions.'],[13,'familyPatterns','Family Patterns','Some patterns began as ways of getting through.'],[14,'familyRoles','Family Survival Roles','Roles we may have learned to survive.'],[15,'childhoodRules','Childhood Rules','Rules I learned without anyone saying them.'],[16,'innerCritic','Inner Critic','A harsh voice can sound convincing without being accurate.'],[17,'boundaries','Boundaries','Protecting my recovery without controlling other people.'],[18,'resentment','Resentment','What am I still carrying?'],[19,'accountability','Accountability','Own the behaviour. Do not become the behaviour.'],[20,'apologies','Apologies and Repair','Words matter. Changed behaviour matters too.'],[21,'connection','Connection and Isolation','Recovery gets harder when my world gets smaller.'],[22,'balance','Recovery Balance','Where is my energy going?'],[23,'working','What Is Working?','Recovery is more than a list of problems.'],[24,'rebuilding','Rebuilding a Life','Recovery cannot be endless analysis.'],[25,'grounding','Grounding and Stillness','Try it. Notice it. Keep what helps.'],[26,'values','Values','What matters enough to guide my next choice?'],[27,'warning','Recovery Warning Signs','What changes before things get worse?'],[28,'support','My Support Map','Recovery does not have to sit on one person’s shoulders.'],[29,'daily','Daily Check-In','One day. One honest look. One next step.'],[30,'closing','Quiet Strength Recovery','My recovery belongs to me.']
  ];

  function nav(href,icon,label,active){return `<a class="nav-btn ${active?'active':''}" href="${href}"><b>${icon}</b>${label}</a>`}
  function workbookPager(r){
    const i=catalog.findIndex(([,id])=>id===r);
    if(i<0)return '';
    const current=catalog[i], prev=i>0?catalog[i-1]:null, next=i<catalog.length-1?catalog[i+1]:null;
    const prevHref=prev?'#'+prev[1]:'#workbook', prevTitle=prev?prev[2]:'Workbook';
    const nextHref=next?'#'+next[1]:'#home', nextTitle=next?next[2]:'Home';
    return `<nav class="workbook-pager no-print" aria-label="Workbook page navigation"><div class="pager-progress">Page ${current[0]} of 30</div><div class="pager-buttons"><a class="pager-btn previous" href="${prevHref}"><span class="pager-arrow">←</span><span><small>Previous</small><strong>${esc(prevTitle)}</strong></span></a><a class="pager-btn next" href="${nextHref}"><span><small>${next?'Next':'Finished'}</small><strong>${esc(nextTitle)}</strong></span><span class="pager-arrow">→</span></a></div></nav>`;
  }
  function shell(content){const r=view();return `<div class="app-shell"><header class="topbar"><a class="brand" href="#home"><div class="brand-mark"><img src="assets/icon.svg" alt="Quiet Strength Recovery logo"></div><div><div class="brand-title">Quiet Strength Recovery</div><div class="brand-sub">Personal Recovery Workbook</div></div></a><div class="top-actions"><a class="btn secondary" href="#help">I need support now</a><button class="lock-button" id="lockNowBtn" type="button" aria-label="Lock Quiet Strength Recovery">🔒 <span>Lock</span></button><div class="status-pill" id="saveStatus" aria-live="polite"></div></div></header><main>${content}${workbookPager(r)}<div class="footer">Quiet Strength Recovery • Free Recovery Guide v1.9 • Based on lived experience • Passcode protected • <a href="#privacy">Privacy</a> • <a href="https://qsrecovery.substack.com/">Substack</a> • <a href="https://www.youtube.com/@quietstrengthrecovery">YouTube</a> • <a href="mailto:quietstrengthrecovery@outlook.com">Email</a> • No completion score. Use what helps.</div></main><nav class="bottom-nav">${nav('#home','⌂','Home',r==='home')}${nav('#workbook','▤','Workbook',r==='workbook'||r==='booklet')}${nav('#daily','☀','Daily',r==='daily'||r==='history'||r==='day')}${nav('#tools','✦','Tools',r==='tools'||interactiveIds.includes(r))}${nav('#support','◎','Support',r==='support'||r==='help'||r==='settings')}</nav></div>`}

  function head(eyebrow,title,copy){return `<section class="page-head"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></section>`}
  function action(href,icon,title,copy,cls=''){return `<a class="card action-card ${cls}" href="${href}"><div><div class="action-icon">${icon}</div><div class="card-title">${title}</div><div class="card-copy">${copy}</div></div><div class="arrow">Open →</div></a>`}
  function controlId(path){return 'qs-'+String(path).replace(/[^a-zA-Z0-9_-]+/g,'-')}
  function field(label,path,type='text',value='',help=''){const id=controlId(path);return `<div class="field"><label for="${id}">${label}</label>${help?`<small>${help}</small>`:''}<input id="${id}" type="${type}" data-path="${path}" value="${esc(value)}"></div>`}
  function area(label,path,value='',help=''){const id=controlId(path);return `<div class="field"><label for="${id}">${label}</label>${help?`<small>${help}</small>`:''}<textarea id="${id}" data-path="${path}">${esc(value)}</textarea></div>`}
  function getPath(path){return path.split('.').reduce((o,k)=>o?.[k],state)}
  function setPath(path,value){const parts=path.split('.');let o=state;for(let i=0;i<parts.length-1;i++){o[parts[i]]??={};o=o[parts[i]]}o[parts.at(-1)]=value;queueSave()}
  function pageData(id){state.pages[id]??={};return state.pages[id]}
  function checklist(label,path,items,help=''){const obj=getPath(path)||{};return `<div class="field"><label>${label}</label>${help?`<small>${help}</small>`:''}<div class="choice-grid">${items.map(x=>`<label class="choice ${obj[x]?'checked':''}"><input type="checkbox" data-checkpath="${path}" data-checkkey="${esc(x)}" ${obj[x]?'checked':''}>${esc(x==='I noticed resentment / self-pity'?'I noticed feeling resentful, hurt or stuck':x)}</label>`).join('')}</div></div>`}
  function chips(label,path,items,help=''){const obj=getPath(path)||{};return `<div class="field"><label>${label}</label>${help?`<small>${help}</small>`:''}<div class="chip-row">${items.map(x=>`<button class="chip ${obj[x]?'active':''}" data-chip-path="${path}" data-chip-key="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>`}
  function infoPage(title,copy,body){return shell(`${head('Quiet Strength Recovery',title,copy)}<div class="card">${body}</div><div class="toolbar"><a class="btn secondary" href="#workbook">Back to workbook</a></div>`)}

  function home(){
    const date=todayISO(), t=state.checkins[date]||{}, recent=state.meta.recentTools||[], out=latestOutput(date);
    const feeling=t.feeling||state.feelings.secondary||state.feelings.primary||'';
    const completed=Object.keys(state.dailyOutputs||{}).sort((a,b)=>b.localeCompare(a)).slice(0,3);
    return shell(`<section class="hero"><div class="eyebrow">Free • Optional • Based on lived experience</div><h1>Quiet Strength</h1><p>Quiet Strength Recovery is a self-guided recovery guide built from lived experience. It shares tools, reflections and routines that helped in real recovery. You choose what, if anything, is useful to you.</p><div class="notice" style="margin:16px 0"><strong>What this is:</strong> a recovery guide and set of optional self-help tools. <strong>What this is not:</strong> medical treatment, diagnosis, counselling, psychotherapy, detoxification or a replacement for professional or emergency care.</div><div class="hero-quote">“I can show you the tools and share what worked for me. You choose what works for you.”</div><div class="hero-actions"><a class="hero-btn" href="#daily">${out?'Open today’s check-in':'Start today’s check-in'}</a><a class="hero-btn alt" href="#history">Daily archive</a><a class="hero-btn alt" href="#recovery">My recovery progress</a><a class="hero-btn alt" href="#help">I need support now</a><a class="hero-btn alt" href="downloads/Quiet-Strength-Recovery-v1.9.apk" download>Download Android APK</a></div></section>
    <div class="dashboard"><div class="dash-stack"><div class="snapshot"><div class="eyebrow">Today</div><h3>How am I doing?</h3>${feeling?`<div class="snapshot-value">${esc(feeling)}</div>`:`<p class="empty">You have not named a feeling today. That is fine.</p>`}<div class="toolbar"><a class="btn" href="#feelings">Check my feelings</a><a class="btn secondary" href="#daily">Daily check-in</a></div></div><div class="snapshot"><div class="eyebrow">Today’s record</div><h3>${out?'Daily output saved':'Not completed yet'}</h3>${out?`<p class="empty">Saved ${esc(formatWhen(out.completedAt))}. You can look back at it any time.</p><a class="btn gold" href="#day/${date}">View today’s output</a>`:`<p class="empty">When you finish your check-in, choose <strong>Complete day & create output</strong>. It becomes a dated record in your archive.</p>`}</div></div>
    <div class="dash-stack"><div class="snapshot"><div class="eyebrow">Your next useful thing</div><h3>${t.today?esc(t.today):'Choose one manageable direction.'}</h3><p class="empty">The aim is not to complete a programme. This is a guide: notice what may help now and leave what does not.</p><a class="btn secondary" href="#daily">Open today</a></div><div class="snapshot"><div class="eyebrow">Recent daily outputs</div><h3>Look back without scoring yourself</h3>${completed.length?`<div class="recent-links">${completed.map(d=>`<a class="recent-link" href="#day/${d}">${esc(d)}</a>`).join('')}</div>`:`<p class="empty">Completed daily outputs will appear here.</p>`}<div class="toolbar"><a class="btn secondary" href="#history">Open archive</a></div></div></div></div>
    ${installPanel()}<div class="client-privacy-link"><a href="#privacy">How privacy and device storage work →</a></div>
    <div class="progress-free"><strong>You cannot fail this guide.</strong> Quiet Strength offers options, reflections and tools. You choose what helps and leave what does not.</div>
    <h2 class="section-title">Quick tools</h2><section class="grid">${action('#daily','☀','Daily Check-In','One day. One honest look. One next step.','primary')}${action('#history','◫','Daily Archive','Every completed day becomes a dated recovery output you can revisit.','soft-blue')}${action('#urges','⌁','I Have an Urge','Create time, space and support before the next choice.','soft-rose')}${action('#brave','B','BRAVE','Create a gap between the trigger and the next decision.','soft-sand')}${action('#warning','△','My Warning Signs','Notice early enough that choices and support are still available.','soft-green')}${action('#support','◎','My Support','Keep trusted people, groups, services, places and routines visible.','soft-lav')}</section>`)
  }
  function workbook(){return shell(`${head('Recovery Guide','Choose what feels useful today.','Quiet Strength is a recovery guide based on lived experience. These optional workbook-style pages are tools within the guide; use only what feels useful to you.')}<div class="toolbar"><a class="btn" href="#booklet">Open print edition</a><a class="btn secondary" href="#history">My check-in history</a></div><div class="list">${catalog.map(([n,id,title,copy])=>`<a class="list-item" href="#${id}"><span class="list-number">${n}</span><span class="list-main"><div class="list-title">${esc(title)}</div><div class="list-meta">${esc(copy)}</div></span><span class="arrow">${interactiveIds.includes(id)?'Use →':'Read →'}</span></a>`).join('')}</div>`)}
  function booklet(){return shell(`${head('Professional Print Edition','The printed guide is a separate option.','Quiet Strength can be used as this digital recovery guide or as the separate Professional Print Edition.')}<div class="card"><h3>Prefer paper?</h3><p class="card-copy">A printed Quiet Strength Recovery guide is available separately. If someone shared the digital guide with you, you can ask whether a paper copy is available.</p><div class="notice"><strong>Your choice matters:</strong> the digital and printed versions are parallel options. You do not need to use both.</div></div><div class="toolbar"><a class="btn secondary" href="#workbook">Back to recovery guide</a></div>`) }


  function welcome(){return infoPage('Welcome','A free, optional recovery guide based on lived experience.',`<div class="notice"><strong>Disclaimer:</strong> Quiet Strength Recovery is a peer-support and educational recovery guide created from lived experience. It is not a medical device and does not diagnose, treat, cure or prevent any medical condition or mental health disorder. The information and tools provided are not a substitute for professional medical advice, clinical therapy or emergency medical intervention. Always consult a qualified healthcare professional for medical advice, diagnosis or treatment. If you or someone else is in immediate danger or crisis, contact local emergency services or a crisis helpline.</div><div class="page-grid" style="margin-top:16px"><div class="info-panel"><h3>One important idea</h3><p>Recovery is not a 100% accurate system. There is no single route that works for everybody.</p></div><div class="info-panel"><h3>Use what helps</h3><p>You can use one page, several pages, one tool, or none of them. The choice stays with you.</p></div><div class="info-panel"><h3>Leave what does not</h3><p>You are not expected to agree with, complete or use every exercise.</p></div><div class="info-panel"><h3>Return later</h3><p>Something that means little today may become useful at another stage.</p></div></div><div class="notice" style="margin-top:16px"><strong>You cannot fail this guide.</strong> Quiet Strength exists to offer options, not instructions you must follow.</div>`)}
  function person(){return infoPage('Person-Centred Recovery','Your choices, not a treatment plan.',`<p>Different people need different things at different times. Structure can help, conversation can help, and sometimes one small practical change is enough.</p><div class="page-grid"><div class="info-panel"><h3>I can choose</h3><p>what feels useful today.</p></div><div class="info-panel"><h3>I can pause</h3><p>if a page feels too much.</p></div><div class="info-panel"><h3>I can ask</h3><p>for help or explanation.</p></div><div class="info-panel"><h3>I can return</h3><p>without calling it failure.</p></div><div class="info-panel"><h3>I can adapt</h3><p>tools to fit my life.</p></div><div class="info-panel"><h3>I can notice</h3><p>what actually works for me.</p></div></div><div class="quote" style="margin-top:18px">This is something that helped me. Have a look at it. See whether anything in it helps you.</div>`)}
  function philosophy(){return infoPage('Quiet Strength Philosophy','Recovery can be compassionate and still be honest.',`<p>Quiet Strength is about awareness, responsibility, connection and doing the next useful thing — without pretending recovery is simple or perfect.</p><div class="page-grid">${[['Honesty','See what is happening without dressing it up.'],['Accountability','Own behaviour without turning it into self-hatred.'],['Choice','Notice the moment where another action may be possible.'],['Connection','Isolation makes recovery harder; safe support matters.'],['Courage','Do difficult things even when you do not feel ready.'],['Consistency','Small repeated actions can matter more than big promises.'],['Compassion','Understand why a pattern exists without excusing harm.'],['Service','Helping someone else can bring perspective and connection.']].map(x=>`<div class="info-panel"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div><div class="quote" style="margin-top:18px">Consequences are not punishment. They are information we can learn from.</div>`)}
  function closing(){return infoPage('Quiet Strength Recovery','My recovery belongs to me.',`<p class="mini-quote">I do not need to get everything right. I can notice what is happening, learn from what goes wrong, ask for help and make a different choice.</p><div class="page-grid">${[['Notice','I can notice what is happening before I automatically act.'],['Learn','I can treat consequences as information and ask what they are showing me.'],['Connect','I can come out of isolation and let safe support become part of the next decision.'],['Choose','I can make one healthier choice without solving the whole journey today.'],['Return','If I lose my way, I can come back. I can keep turning up.']].map(x=>`<div class="info-panel"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>${area('My next healthier step','notes.nextStep',state.notes.nextStep||'','One useful action.')}`)}

  function daily(){const {param,invalidParam}=hashParts();const date=param||todayISO();state.checkins[date]??={date,feeling:'',today:'',g1:'',g2:'',g3:'',flags:{},wentWell:'',learn:'',tomorrow:''};const d=state.checkins[date];const base=`checkins.${date}`;const out=latestOutput(date);const flags=['I isolated','I connected','I helped somebody','I did a difficult thing anyway','I noticed resentment / self-pity','I need to repair something'];return shell(`${head('Daily Check-In','One day. One honest look. One next step.','Use this page as often or as rarely as it helps. It is a prompt for awareness, not a test. Nothing has to be filled in perfectly.')}${invalidParam?'<div class="notice" role="alert">That date could not be opened. Showing today’s check-in instead.</div>':''}<div class="toolbar"><a class="btn secondary" href="#history">View daily archive</a>${out?`<a class="btn gold" href="#day/${date}">View saved output</a>`:''}</div><div class="card">${field('Date',`${base}.date`,'date',date)}${field('Morning feeling',`${base}.feeling`,'text',d.feeling,'How do I feel?')}${area('Just for today I will…',`${base}.today`,d.today,'What is one healthier direction I can choose today?')}<div class="field"><label>Three things I am grateful for</label><div class="tool-grid">${field('1',`${base}.g1`,'text',d.g1)}${field('2',`${base}.g2`,'text',d.g2)}${field('3',`${base}.g3`,'text',d.g3)}</div></div>${checklist('What showed up today?',`${base}.flags`,flags)}${area('What went well?',`${base}.wentWell`,d.wentWell,'Something worth noticing, however small.')}${area('What was difficult / what did I learn?',`${base}.learn`,d.learn,'Without attacking myself.')}${area('One thing I can carry into tomorrow',`${base}.tomorrow`,d.tomorrow,'A lesson, intention or useful action.')}<div class="complete-panel"><div><div class="eyebrow">End of day</div><h3>${out?'Update today’s saved output':'Create today’s daily output'}</h3><p>Your output is a clean dated record of your own words. Blank sections are allowed. There is no score.</p></div><button class="btn gold" data-complete-day="${date}">${out?'Update daily output':'Complete day & create output'}</button></div></div>`) }
  function history(){const dates=[...new Set([...Object.keys(state.checkins||{}),...Object.keys(state.dailyOutputs||{})])].sort((a,b)=>b.localeCompare(a));return shell(`${head('Daily Archive','A dated record you can look back at.','When a day is completed, Quiet Strength creates a daily recovery output from your own entries. Draft check-ins remain available too.')}<div class="toolbar"><a class="btn" href="#daily">Open today’s check-in</a><button class="btn secondary" id="downloadArchiveBtn">Download completed archive</button></div><div class="field archive-search"><label for="historySearch">Find a day or word</label><input id="historySearch" type="search" placeholder="Search dates, feelings or reflections…"></div>${dates.length?`<div class="list" id="historyList">${dates.map(date=>{const d=state.checkins[date]||{};const out=latestOutput(date);const searchable=[date,d.feeling,d.today,d.wentWell,d.learn,d.tomorrow].join(' ').toLowerCase();return `<div class="history-card ${out?'completed':''}" data-search="${esc(searchable)}"><div class="history-date">${esc(date)}<small>${esc(formatDay(date))}</small></div><div><div class="history-status ${out?'done':'draft'}">${out?'Daily output saved':'Draft check-in'}</div><strong>${esc(d.feeling||'No feeling entered')}</strong><div class="history-summary">${esc(d.today||d.wentWell||d.learn||'No written reflection yet.')}</div></div><div class="history-actions">${out?`<a class="btn gold" href="#day/${date}">View output</a>`:''}<a class="btn secondary" href="#daily/${date}">${out?'Edit check-in':'Continue'}</a></div></div>`}).join('')}</div>`:`<div class="notice">No check-ins saved yet.</div>`}`)}
  function dayOutput(){const date=hashParts().param||todayISO();const out=latestOutput(date);if(!out)return shell(`${head('Daily Recovery Output','No completed output for this day.','Open the check-in, then choose Complete day & create output when you want to save the day as a dated record.')}<div class="toolbar"><a class="btn" href="#daily/${date}">Open check-in</a><a class="btn secondary" href="#history">Back to archive</a></div>`);const d=out.checkin||{};const selected=Object.entries(d.flags||{}).filter(([,v])=>v).map(([k])=>k);const tools=(out.toolsUsed||[]).map(id=>names[id]||id);const versions=outputVersions(date);return shell(`${head('Daily Recovery Output',formatDay(date),'A clean record of what you entered that day. This is not a score, diagnosis or clinical assessment.')}<div class="toolbar no-print"><a class="btn secondary" href="#history">Back to archive</a><a class="btn secondary" href="#daily/${date}">Edit check-in</a><button class="btn gold" id="printDayBtn">Print / Save as PDF</button><button class="btn" data-download-day="${date}">Download text</button></div><article class="daily-report" id="dailyReport"><div class="report-brand"><div class="brand-mark"><img src="assets/icon.svg" alt="Quiet Strength Recovery logo"></div><div><div class="eyebrow">Quiet Strength Recovery</div><h2>Daily Recovery Output</h2></div></div><div class="report-meta"><strong>${esc(formatDay(date))}</strong><span>Completed ${esc(formatWhen(out.completedAt))}</span>${versions.length>1?`<span>Saved version ${versions.length}</span>`:''}</div>${reportBlock('Morning feeling',d.feeling)}${reportBlock('Just for today I will…',d.today)}<section class="report-block"><h3>Three things I am grateful for</h3><ol><li>${esc(d.g1||'—')}</li><li>${esc(d.g2||'—')}</li><li>${esc(d.g3||'—')}</li></ol></section><section class="report-block"><h3>What showed up today?</h3>${selected.length?`<div class="report-chips">${selected.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'<p>—</p>'}</section>${reportBlock('What went well?',d.wentWell)}${reportBlock('What was difficult / what did I learn?',d.learn)}${reportBlock('One thing I can carry into tomorrow',d.tomorrow)}<section class="report-block"><h3>Tools used that day</h3><p>${tools.length?esc(tools.join(' • ')):'No tools recorded.'}</p></section><footer class="report-footer">My recovery belongs to me. I can notice, learn, connect, choose and return.</footer></article>`)}
  function reportBlock(title,value){return `<section class="report-block"><h3>${title}</h3><p>${esc(value||'—').replace(/\n/g,'<br>')}</p></section>`}

  function brave(){const d=state.brave;const steps=[['B','Break the moment','Interrupt the automatic reaction. Even a few seconds can create a gap.','break'],['R','Recognise','Name the feeling, thought, urge, fear, anger, isolation or behaviour.','recognise'],['A','Accountability','Own your behaviour and your next decision without unnecessary shame.','accountability'],['V','View the bigger picture','Where will this decision take me? What matters more than this moment?','view'],['E','Execute the better action','Make the healthier next move: walk away, call, wait, apologise, connect, write, or do not act on the urge.','execute']];return shell(`${head('The BRAVE Tool','Create a gap between the trigger and the next decision.','BRAVE is one Quiet Strength tool. It is not compulsory and it is not the only route. Use it when it helps you slow an automatic reaction.')}<div class="card">${steps.map(x=>`<div class="brave-step"><div class="brave-letter">${x[0]}</div><div>${area(x[1],`brave.${x[3]}`,d[x[3]],x[2])}</div></div>`).join('')}</div>`)}
  function urges(){const d=state.urges;return shell(`${head('Urges and Cravings','An urge is real. It is not an instruction.','The discomfort may be strong. The purpose of this page is to create enough time and support to choose what happens next.')}<div class="card"><div class="sequence"><span>TRIGGER</span><b>→</b><span>URGE BUILDS</span><b>→</b><span>PEAK</span><b>→</b><span>WAIT + CHOOSE</span></div>${area('1. Notice','urges.body',d.body,'Where do I feel the urge in my body?')}${area('2. Name','urges.underneath',d.underneath,'What happened just before it? What feeling is underneath?')}${area('3. Create space','urges.space',d.space,'Can I leave, change rooms, go outside or delay the action?')}${area('4. Connect','urges.connect',d.connect,'Who can I call, message or sit with safely?')}${area('5. Choose','urges.choose',d.choose,'What consequence would using create? What healthier action is available?')}</div><div class="safety" style="margin-top:16px"><strong>Medical / emergency support:</strong> Do not rely on this exercise for dangerous withdrawal, serious medical symptoms or immediate risk of harm. Use appropriate medical, emergency or professional support.</div>`)}
  const feelingsMap={Happy:['content','hopeful','proud'],Surprised:['startled','confused','amazed'],Fearful:['anxious','insecure','overwhelmed'],Sad:['lonely','disappointed','grieving'],Disgusted:['uneasy','disapproving','repelled'],Angry:['frustrated','resentful','hurt']};
  function feelings(){const d=state.feelings;const subs=d.primary?feelingsMap[d.primary]:[];return shell(`${head('Feelings','Feelings are information, not instructions.','You do not need the perfect word. Start with the closest fit, then notice what may be underneath it.')}<div class="card"><div class="field"><label>What am I feeling?</label><div class="feeling-grid">${Object.keys(feelingsMap).map(f=>`<button class="feeling-btn ${d.primary===f?'active':''}" data-feeling="${f}">${f}</button>`).join('')}</div><div class="subfeelings">${subs.map(s=>`<button class="chip ${d.secondary===s?'active':''}" data-subfeeling="${s}">${s}</button>`).join('')}</div></div>${area('Where do I feel it?','feelings.where',d.where,'Chest, stomach, jaw, shoulders, hands…')}${area('What would support me now?','feelings.support',d.support,'Not what removes every feeling — what supports me?')}<div class="quote">I can feel something strongly without letting that feeling make every decision for me.</div></div>`)}

  function moment(){const d=pageData('moment');return shell(`${head('The Moment Before the Action','Map what happened — not to judge it, but to understand it.','Automatic behaviour often has a chain. Seeing the chain can reveal where another choice, delay or connection might have been possible.')}<div class="card"><div class="sequence"><span>TRIGGER</span><b>→</b><span>THOUGHT</span><b>→</b><span>FEELING</span><b>→</b><span>URGE</span><b>→</b><span>CHOICE</span><b>→</b><span>ACTION</span><b>→</b><span>CONSEQUENCE</span><b>→</b><span>WHAT I LEARN</span></div>${[['Trigger','trigger'],['Thought','thought'],['Feeling','feeling'],['Urge','urge'],['Choice','choice'],['Action','action'],['Consequence','consequence'],['What I learn','learn']].map(x=>area(x[0],`pages.moment.${x[1]}`,d[x[1]]||'')).join('')}${area('Where was the earliest point I could have done something different?','pages.moment.earliest',d.earliest||'')}</div>`)}
  function consequences(){const d=pageData('consequences');return shell(`${head('Consequences','Consequences are information, not punishment.','Compassion does not mean pretending nothing happened. We can look honestly at the cost of a choice without humiliating ourselves.')}<div class="card"><div class="page-grid"><div class="info-panel"><h3>Accountability</h3><p>“I did that. What can I learn and do differently?”</p></div><div class="info-panel"><h3>Shame</h3><p>“I am terrible and will never change.”</p></div></div>${area('What happened?','pages.consequences.happened',d.happened||'','Keep it factual.')}${area('What led up to it?','pages.consequences.ledUp',d.ledUp||'','Look earlier than the final moment.')}${area('What did it cost?','pages.consequences.cost',d.cost||'','Time, trust, money, health, opportunity, peace?')}${area('What warning signs were there?','pages.consequences.warning',d.warning||'','What changed before the action?')}${area('Where was another choice possible?','pages.consequences.choice',d.choice||'','Even if the window was small.')}${area('What might help next time?','pages.consequences.next',d.next||'','One realistic support, boundary, delay or action.')}</div>`)}
  function rhythm(){const d=pageData('rhythm');return shell(`${head('Daily Recovery Rhythm','Simple practices can make the day easier to see clearly.','Use the parts that help. This is not a routine you have to perform perfectly.')}<div class="card">${area('Morning','pages.rhythm.morning',d.morning||'','How do I feel? What is on my mind? What do I need? What am I afraid of?')}${area('Just for today','pages.rhythm.today',d.today||'','What is one healthier direction I can focus on today?')}${area('Connection','pages.rhythm.connection',d.connection||'','Did I answer, say hello, message, call or ask for help?')}${area('Difficult things','pages.rhythm.difficult',d.difficult||'','What did I not want to do — and did I do it anyway?')}${area('Service','pages.rhythm.service',d.service||'','Did I listen, help, or reach out to somebody who may be struggling?')}${area('Basic needs','pages.rhythm.needs',d.needs||'','Sleep, food, medication as prescribed, movement, rest — what needs attention?')}${area('Evening','pages.rhythm.evening',d.evening||'','What went well? Was I honest? Do I owe repair? Did fear or self-pity make decisions for me? What can I learn without attacking myself?')}</div>`)}
  function fear(){const d=pageData('fear');return shell(`${head('Fear','Fear: fact or story?','Fear can contain useful information and imagined catastrophe at the same time. Separate what you know from what your mind is predicting.')}<div class="card">${area('What am I afraid of?','pages.fear.afraid',d.afraid||'')}${area('What do I actually know?','pages.fear.know',d.know||'')}${area('What am I imagining?','pages.fear.imagining',d.imagining||'')}${area('What can I control?','pages.fear.control',d.control||'')}${area('One BRAVE next action','pages.fear.action',d.action||'')}</div>`)}
  function perspective(){const d=pageData('perspective');return shell(`${head('Perspective','Self-pity without self-attack: flip the negative.','Thoughts such as “why me?”, “nobody cares” or “what is the point?” can shrink our view. The aim is not fake positivity — it is a wider, fairer picture.')}<div class="card">${area('What happened?','pages.perspective.happened',d.happened||'','Describe the situation.')}${area('What story am I telling myself?','pages.perspective.story',d.story||'','What is my mind adding?')}${area('What facts am I ignoring?','pages.perspective.facts',d.facts||'','What else is true?')}${area('What can I be grateful for?','pages.perspective.grateful',d.grateful||'','Something real, not forced.')}${area('What is in my control?','pages.perspective.control',d.control||'','Where do I still have influence?')}${area('What action helps rather than hurts?','pages.perspective.action',d.action||'','One next step.')}<div class="quote">A wider view does not erase the difficulty. It gives me more choices inside it.</div></div>`)}
  function familyPatterns(){const d=pageData('familyPatterns');const patterns=['Stay alert — hypervigilance, scanning, anxiety','Keep quiet — hiding feelings or problems','Keep everyone happy — people pleasing or controlling','Do not need too much — neglecting my own needs','Handle it yourself — isolation or difficulty asking for help'];return shell(`${head('Family Patterns','Some patterns began as ways of getting through.','This is not about forcing a childhood explanation onto every behaviour. Notice only what fits. You may skip this page and return later.')}<div class="card">${chips('Patterns I recognise','pages.familyPatterns.patterns',patterns,'Choose only what feels familiar.')}${area('One pattern I recognise','pages.familyPatterns.one',d.one||'')}${area('How might it have protected me?','pages.familyPatterns.protected',d.protected||'')}${area('How does it show up today?','pages.familyPatterns.today',d.today||'')}${area('What do I need now?','pages.familyPatterns.need',d.need||'')}<div class="quote">Understanding a pattern does not remove responsibility. It gives me more information about what I can choose now.</div></div>`)}
  function familyRoles(){const d=pageData('familyRoles');const roles=[['Hero','Trying to be capable, responsible or successful enough to hold things together.'],['Lost Child','Staying quiet, disappearing or avoiding attention because being unseen can feel safer.'],['Mascot','Using humour, performance or distraction to reduce tension or hide pain.'],['Scapegoat','Carrying blame, acting out or becoming the focus when wider tension has nowhere else to go.'],['Caretaker','Looking after everybody else while your own needs are pushed to the side.']];return shell(`${head('Family Survival Roles','Roles we may have learned to survive.','You may recognise more than one, move between them, or recognise none. These are patterns to explore — not diagnoses or permanent labels.')}<div class="card"><div class="roles-grid">${roles.map(x=>`<div class="role-card"><h4>${x[0]}</h4><p>${x[1]}</p></div>`).join('')}</div>${chips('Which roles do I recognise?','pages.familyRoles.roles',roles.map(x=>x[0]))}${area('How did it protect me?','pages.familyRoles.protected',d.protected||'')}${area('What did it cost me?','pages.familyRoles.cost',d.cost||'')}${area('What do I need now?','pages.familyRoles.need',d.need||'')}<div class="quote">These may have been survival patterns. Recognising one is not a personal failure.</div></div>`)}
  function childhoodRules(){const d=pageData('childhoodRules');const rules=['Do not talk about problems.','Do not trust.','Do not show feelings.','Do not ask for help.','Keep everyone happy.','Do not make mistakes.','Stay invisible.','Be strong no matter what.','Look after everybody else.','Never let people see what is really happening.'];return shell(`${head('Childhood Rules','Rules I learned without anyone saying them.','Tick only what feels familiar. Leave the rest. If this page feels too much today, skip it and return only if it becomes useful.')}<div class="card">${checklist('Rules that feel familiar','pages.childhoodRules.rules',rules)}<div class="divider"></div><h3>Rewrite one old rule</h3>${area('The old rule','pages.childhoodRules.old',d.old||'','What rule did I learn?')}${area('How it protected me','pages.childhoodRules.protected',d.protected||'','What did following it help me avoid or manage?')}${area('Does it still serve me?','pages.childhoodRules.serve',d.serve||'','Where does it now limit, isolate or hurt me?')}${area('A healthier rule I could try','pages.childhoodRules.healthier',d.healthier||'','Write something realistic that fits the life I want now.')}</div>`)}
  function innerCritic(){const d=pageData('innerCritic');return shell(`${head('Inner Critic','A harsh voice can sound convincing without being accurate.','The goal is not to replace every difficult thought with a slogan. It is to respond more fairly and usefully.')}<div class="card">${area('What does my inner critic say?','pages.innerCritic.say',d.say||'','Write the actual words.')}${area('Whose voice does it sound like?','pages.innerCritic.voice',d.voice||'','Mine, somebody from the past, culture, fear?')}${area('Would I speak to someone else this way?','pages.innerCritic.other',d.other||'','If not, what is different?')}${area('What is the fact?','pages.innerCritic.fact',d.fact||'','Strip away insults and predictions.')}${area('What would a fairer response sound like?','pages.innerCritic.fair',d.fair||'','Grounded, not sugary.')}${area('What action helps me now?','pages.innerCritic.action',d.action||'','What can I actually do?')}</div>`)}
  function boundaries(){const d=pageData('boundaries');return shell(`${head('Boundaries','Protecting my recovery without controlling other people.','A boundary is about what I will do, accept, refuse or step away from. It is not a way of forcing somebody else to behave how I want.')}<div class="card"><div class="notice">Common patterns can include saying yes when I mean no, over-explaining decisions, people pleasing to avoid conflict, or rescuing people from consequences.</div>${area('Situation','pages.boundaries.situation',d.situation||'','What is happening?')}${area('What I normally do','pages.boundaries.normal',d.normal||'','Agree, rescue, control, explain, avoid?')}${area('What I actually need','pages.boundaries.need',d.need||'','What protects my wellbeing or recovery?')}${area('Boundary I could try','pages.boundaries.boundary',d.boundary||'','What can I say or do clearly?')}${area('What I fear will happen','pages.boundaries.fear',d.fear||'','Rejection, anger, guilt, misunderstanding?')}${area('If it is ignored, what will I do?','pages.boundaries.ignored',d.ignored||'','A boundary needs an action I control.')}<div class="quote">Feeling guilty after setting a boundary does not automatically mean the boundary was wrong.</div></div>`)}
  function resentment(){const d=pageData('resentment');return shell(`${head('Resentment','What am I still carrying?','This is not about excusing anyone. It is about seeing what I am carrying, what belongs to me now, and what may help.')}<div class="card">${area('Who or what am I resentful towards?','pages.resentment.who',d.who||'','Name the person, situation, institution or event.')}${area('What happened?','pages.resentment.happened',d.happened||'','Keep it clear and specific.')}${area('What feeling sits underneath it?','pages.resentment.feeling',d.feeling||'','Hurt, fear, grief, shame, disappointment?')}${area('What am I still carrying?','pages.resentment.carrying',d.carrying||'','An argument, wish for justice, need to be understood?')}${area('Is there anything I need to own?','pages.resentment.own',d.own||'','My behaviour, words or how I handle it now.')}${area('What can I not change?','pages.resentment.cannot',d.cannot||'','Name what is outside my control.')}${area('What boundary or action might help?','pages.resentment.action',d.action||'','Distance, support, conversation, decision, or nothing for now.')}${area('What would carrying less look like?','pages.resentment.less',d.less||'','You do not have to be ready to “let go” today.')}</div>`)}
  function accountability(){const d=pageData('accountability');return shell(`${head('Accountability','Own the behaviour. Do not become the behaviour.','Accountability makes room for change. Shame turns one action into an identity.')}<div class="card"><div class="sequence"><span>NOTICE</span><b>→</b><span>IMPACT</span><b>→</b><span>OWN</span><b>→</b><span>LEARN</span></div>${area('What am I taking responsibility for?','pages.accountability.responsibility',d.responsibility||'','Be specific.')}${area('What was the impact?','pages.accountability.impact',d.impact||'','What consequence did it have?')}${area('What can I repair or change now?','pages.accountability.repair',d.repair||'','Action, boundary, apology, routine?')}${area('What can I not undo?','pages.accountability.undo',d.undo||'','Name it honestly.')}${area('What will I do differently next time?','pages.accountability.next',d.next||'','One practical behaviour, not perfection.')}</div>`)}
  function apologies(){const d=pageData('apologies');return shell(`${head('Apologies and Repair','Words matter. Changed behaviour matters too.','An apology can be part of repair, but it should not be used simply to make our own discomfort disappear. Contact is not always safe or appropriate.')}<div class="card"><div class="notice">Before contact: Do I understand what I am apologising for? Am I prepared for them not to accept it? Am I taking responsibility without excuses? Is contact safe and appropriate for everyone?</div>${area('Do I owe an apology?','pages.apologies.owe',d.owe||'','Who, and for what behaviour?')}${area('What am I taking responsibility for?','pages.apologies.responsibility',d.responsibility||'','Keep the focus on what I did.')}${area('Why do I want to apologise?','pages.apologies.why',d.why||'','Repair harm, or mainly remove my guilt?')}${area('What would changed behaviour look like?','pages.apologies.changed',d.changed||'','What would be visible over time?')}${area('Is direct contact safe and appropriate?','pages.apologies.safe',d.safe||'','If not, what other accountability or repair is possible?')}<div class="safety">If contact could create harm, danger, harassment or unwanted pressure, repair may need to happen without direct contact.</div></div>`)}
  function connection(){const d=pageData('connection');const options=['Say hello to somebody safe','Answer a message','Send a message','Call someone I trust','Attend recovery / support','Ask for help','Spend time around safe people','Help somebody without rescuing them'];return shell(`${head('Connection and Isolation','Recovery gets harder when my world gets smaller.','Safe connection can begin quietly: answering a message, sitting around people, calling someone trusted or asking for help.')}<div class="card"><div class="page-grid"><div class="info-panel"><h3>When I withdraw</h3><p>Avoid people → more time in my head → less perspective → recovery feels heavier.</p></div><div class="info-panel"><h3>When I connect safely</h3><p>One small action → contact → perspective → support becomes easier to use.</p></div></div>${checklist('Small connection options','pages.connection.options',options)}${area('One small connection today','pages.connection.today',d.today||'','Who or where feels safe enough?')}${area('What changed afterwards?','pages.connection.changed',d.changed||'','Even slightly — mood, urge, thinking, isolation?')}<div class="quote">Connection does not have to be deep or dramatic. Sometimes recovery starts with simply not disappearing.</div></div>`)}
  function working(){const d=pageData('working');return shell(`${head('What Is Working?','Recovery is more than a list of problems.','Notice what is already helping. Strengths, people, routines and moments of relief are evidence too.')}<div class="card">${area('What has kept me going so far?','pages.working.kept',d.kept||'','Persistence, humour, honesty, stubbornness, kindness, courage, asking for help, turning up — what have I actually used?')}${area('What is already working?','pages.working.working',d.working||'','Routine, meeting, person, habit, boundary?')}${area('Who supports me?','pages.working.supports',d.supports||'','Who can I be real with?')}${area('What activities help me?','pages.working.activities',d.activities||'','What settles, moves or focuses me?')}${area('What makes me laugh?','pages.working.laugh',d.laugh||'','People, comedy, memories, daft things?')}${area('What gives peace or meaning?','pages.working.peace',d.peace||'','Nature, values, family, faith, service?')}${area('What do I want more of?','pages.working.more',d.more||'','What did addiction push out?')}</div>`)}
  function rebuilding(){const d=pageData('rebuilding');const cats=[['music','Music','Songs, artists, playlists'],['humour','Humour','Comedy, people, moments'],['hobbies','Hobbies','Things I make or do'],['outdoors','Outdoors','Walking, nature, places'],['films','Films / Books','Stories that stay with me'],['movement','Movement','Exercise, sport, stretching'],['rest','Rest','Sleep, quiet, switching off'],['food','Food / Nourishment','Cooking, regular meals, enjoyment'],['creativity','Creativity','Drawing, writing, making'],['other','Other','Something that matters to me']];return shell(`${head('Rebuilding a Life','Recovery cannot be endless analysis.','Stopping the substance is only part of the work. What makes life feel like yours again?')}<div class="card"><div class="category-grid">${cats.map(([k,l,h])=>`<div class="category-box"><label for="qs-rebuilding-${k}">${l}</label><small>${h}</small><input id="qs-rebuilding-${k}" aria-label="${l}" data-path="pages.rebuilding.${k}" value="${esc(d[k]||'')}" placeholder="Add what matters to you…"></div>`).join('')}</div>${area('One ordinary thing I want more of','pages.rebuilding.more',d.more||'','A routine, interest, meal, walk, laugh, song, person, place or part of myself I want to reconnect with.')}</div>`)}
  function grounding(){const d=pageData('grounding');const opts=[['Slow the breath','Breathe gently. Let the out-breath be a little longer. Repeat without forcing it.'],['5 things I can see','Name five things clearly. Notice shape, colour and detail.'],['Feet + body','Notice the floor, chair, hands, jaw and shoulders.'],['Walk + notice','Walk slowly enough to notice sounds, colours and movement.']];return shell(`${head('Grounding and Stillness','Try it. Notice it. Keep what helps.','There is no required spiritual approach here. These are simply ways of slowing the moment down and bringing attention back to now.')}<div class="card"><div class="ground-options">${opts.map(x=>`<div class="ground-card"><h4>${x[0]}</h4><p>${x[1]}</p></div>`).join('')}</div>${chips('Which one did I try?','pages.grounding.tried',opts.map(x=>x[0]),'Try one for 60 seconds. The aim is not to make every feeling disappear.')}${area('What did I notice?','pages.grounding.notice',d.notice||'','Body, breath, thoughts, tension, surroundings.')}${area('Would I use this again?','pages.grounding.again',d.again||'','Yes, no, maybe — and when?')}</div>`)}
  function values(){const d=pageData('values');const vals=['Honesty','Family','Courage','Loyalty','Kindness','Freedom','Stability','Respect','Service','Humour','Responsibility','Connection','Health','Creativity','Spirituality'];return shell(`${head('Values','What matters enough to guide my next choice?','Values are qualities I want my actions to move towards — especially when the moment is difficult.')}<div class="card">${chips('Values that matter to me','pages.values.selected',vals)}${field('My own value','pages.values.own','text',d.own||'')}${area('My five anchors','pages.values.anchors',d.anchors||'','Write five values you want close when the moment is difficult.')}${area('Where does addiction pull me away?','pages.values.away',d.away||'','Which value becomes harder to live?')}${area('One value I can live today','pages.values.today',d.today||'','What would it look like as an actual behaviour?')}</div>`)}

  function balance(){const d=state.balance;const labels={recovery:'Recovery',sleep:'Sleep',work:'Work / Purpose',family:'Family',health:'Health',connection:'Connection',service:'Service',enjoyment:'Enjoyment'};return shell(`${head('Recovery Balance','Where is my energy going?','Rate each area from 0 to 10. This is not a scorecard. Rename a category if another part of life matters more to you.')}<div class="card"><div class="balance-layout"><div class="wheel-wrap">${wheelSvg(d,labels)}</div><div>${Object.entries(labels).map(([k,l])=>`<div class="balance-row"><strong>${l}</strong><input type="range" min="0" max="10" step="1" value="${Number(d[k])}" data-balance="${k}" aria-label="${l} rating from 0 to 10"><div class="balance-num" id="num-${k}">${Number(d[k])}</div></div>`).join('')}</div></div><div class="divider"></div>${area('What is being neglected?','notes.balanceNeglected',state.notes.balanceNeglected||'','Which area needs a little more care?')}${area('One small adjustment','notes.balanceAdjustment',state.notes.balanceAdjustment||'','What is realistic enough to try this week?')}</div>`)}
  function wheelSvg(d,labels){const keys=Object.keys(labels),cx=150,cy=150,max=105;const angle=i=>(-Math.PI/2)+(i*2*Math.PI/keys.length);const pt=(i,r)=>[cx+Math.cos(angle(i))*r,cy+Math.sin(angle(i))*r];const rings=[.25,.5,.75,1].map(fr=>`<circle class="ring" cx="${cx}" cy="${cy}" r="${max*fr}"/>`).join('');const spokes=keys.map((k,i)=>{const [x,y]=pt(i,max);return `<line class="spoke" x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"/>`}).join('');const points=keys.map((k,i)=>{const [x,y]=pt(i,max*(Number(d[k])/10));return `${x.toFixed(1)},${y.toFixed(1)}`}).join(' ');const dots=keys.map((k,i)=>{const [x,y]=pt(i,max*(Number(d[k])/10));return `<circle class="point" cx="${x}" cy="${y}" r="4"/>`}).join('');const texts=keys.map((k,i)=>{const [x,y]=pt(i,max+28);return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle">${labels[k]}</text>`}).join('');return `<svg class="wheel" viewBox="0 0 300 300" role="img" aria-label="Recovery balance wheel">${rings}${spokes}<polygon class="shape" id="wheelShape" points="${points}"/>${dots}${texts}</svg>`}
  function support(){const d=state.support;const nodes=[['trusted','Trusted people','node-1'],['peers','Recovery peers','node-2'],['family','Family / safe people','node-3'],['professional','Professional support','node-4'],['medical','Medical / crisis support','node-5'],['groups','Groups / meetings','node-6'],['places','Positive places','node-7'],['activities','Activities / routines','node-8']];return shell(`${head('My Support Map','Recovery does not have to sit on one person’s shoulders.','Put real names, groups, services, places and activities on this map. Blank spaces are allowed.')}<div class="card"><div class="support-map"><div class="support-center">ME<br>MY RECOVERY</div>${nodes.map(([k,l,c])=>`<div class="support-node ${c}"><label for="qs-support-${k}">${l}</label><input id="qs-support-${k}" aria-label="${l}" data-path="support.${k}" value="${esc(d[k])}" placeholder="Add here…"></div>`).join('')}</div>${area('Who or what is missing from my map?','notes.supportMissing',state.notes.supportMissing||'','Is there one safe person, group, medical/professional service, place or activity I could add? What would make asking for help easier?')}</div><div class="safety" style="margin-top:16px"><strong>When more help is needed:</strong> This workbook supports non-clinical recovery mentoring. It does not replace medical care, detoxification, psychiatric care, counselling, psychotherapy, emergency support or safeguarding services.</div>`)}
  function warning(){const d=state.warning;return shell(`${head('Recovery Warning Signs','What changes before things get worse?','Warning signs are personal. The aim is to notice early enough that I still have choices and support available.')}<div class="tool-grid"><div class="card" style="background:var(--green)"><h3>GREEN — Maintain</h3><p>I am generally connected.</p><p><strong>Action:</strong> Keep routines, support and basic care going.</p>${area('My own green signs','warning.green',d.green,'answering people • using support • reasonable sleep / food')}</div><div class="card" style="background:var(--sand)"><h3>AMBER — Act early</h3><p>Something is slipping.</p><p><strong>Action:</strong> Tell someone, reconnect, reduce isolation, return to basics.</p>${area('My own amber signs','warning.amber',d.amber,'isolating • feeling hurt or stuck • skipping routines')}</div><div class="card" style="background:var(--rose)"><h3>RED — Get support now</h3><p>I should not manage this alone.</p><p><strong>Action:</strong> Use trusted people and appropriate professional / crisis support.</p>${area('My own red signs','warning.red',d.red,'lying / hiding • romanticising use • cutting off support')}</div></div>`)}

  function tools(){return shell(`${head('Interactive Tools','Use what helps.','You can use one tool, several tools, or simply talk something through.')}<section class="grid">${action('#brave','B','BRAVE','Create a gap before the next decision.','soft-sand')}${action('#urges','⌁','Urges & Cravings','An urge is real. It is not an instruction.','soft-rose')}${action('#feelings','◉','Feelings','Name what is happening.','soft-blue')}${action('#balance','◔','Recovery Balance','Notice where your energy is going.','soft-lav')}${action('#warning','△','Warning Signs','Notice early changes before things get worse.','soft-green')}${action('#support','◎','Support Map','Keep support visible and easy to reach.','primary')}${action('#boundaries','↔','Boundaries','Protect recovery without controlling other people.','soft-blue')}${action('#resentment','◌','Resentment','See what you are still carrying.','soft-sand')}${action('#grounding','⌾','Grounding','Try it. Notice it. Keep what helps.','soft-green')}</section>`)}
  function help(){return shell(`${head('Support Now','Use the next useful thing.','This screen brings the quickest support tools together.')}<div class="help-now"><h2>You do not have to solve everything right now.</h2><p>Choose the next action that is safe and useful for this moment.</p><div class="help-actions"><a class="help-action" href="#support">Open my support map<small>Trusted people, recovery peers, professionals, services and groups.</small></a><a class="help-action" href="#urges">I have an urge<small>Create time, space and support before the next choice.</small></a><a class="help-action" href="#grounding">Grounding & stillness<small>Slow the moment down and bring attention back to now.</small></a><a class="help-action" href="#brave">Use BRAVE<small>Create a gap between the trigger and the next decision.</small></a><a class="help-action" href="#warning">My warning signs<small>Green, amber and red actions.</small></a><a class="help-action" href="#connection">Connection<small>Take one small safe connection action.</small></a></div></div>${urgentSupportContent()}<div class="safety" style="margin-top:16px"><strong>Important:</strong> This workbook does not replace medical care, detoxification, psychiatric care, counselling, psychotherapy, emergency support or safeguarding services. If someone is medically unwell, in dangerous withdrawal, at immediate risk of suicide or serious harm, or poses a serious risk to others, appropriate professional or emergency support is required.</div>`)}
  const recoveryMilestones=[
    {days:1,label:'24 Hours'},{days:7,label:'1 Week'},{days:30,label:'30 Days'},{days:60,label:'60 Days'},{days:90,label:'90 Days'},
    {days:180,label:'6 Months'},{days:365,label:'1 Year'},{days:730,label:'2 Years'},{days:1095,label:'3 Years'},{days:1825,label:'5 Years'},{days:3650,label:'10 Years'}
  ];
  function recoveryDays(){const start=state.recovery?.startDate;if(!isISODate(start)||start>todayISO())return null;return Math.floor((Date.parse(todayISO()+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000)}
  function formatStorageBytes(n){if(!n)return 'under 1 KB';if(n<1024)return n+' bytes';if(n<1024*1024)return (n/1024).toFixed(1)+' KB';return (n/(1024*1024)).toFixed(2)+' MB'}
  function storedStateSize(){try{return new Blob([JSON.stringify(state)]).size}catch{return 0}}
  function dailyHistoryDates(){return [...new Set([...Object.keys(state.checkins||{}),...Object.keys(state.dailyOutputs||{}),...Object.keys(state.dailyUsage||{})])]}
  function deleteDailyHistoryOlderThan(days){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-days);const cutoff=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,removed=new Set();for(const bucket of ['checkins','dailyOutputs','dailyUsage'])for(const date of Object.keys(state[bucket]||{}))if(date<cutoff){delete state[bucket][date];removed.add(date)}return removed.size}
  function deleteAllDailyHistory(){const count=dailyHistoryDates().length;state.checkins={};state.dailyOutputs={};state.dailyUsage={};return count}
  function recovery(){const r=state.recovery||{},days=recoveryDays(),earned=days===null?[]:recoveryMilestones.filter(m=>days>=m.days),next=days===null?recoveryMilestones[0]:recoveryMilestones.find(m=>days<m.days),completed=Object.keys(state.dailyOutputs||{}).length,checkins=Object.keys(state.checkins||{}).length,tools=new Set(Object.values(state.dailyUsage||{}).flat()).size;const badge=days===null?'<div class="sober-badge unset"><strong>Set your recovery date</strong><span>Your counter starts from the date you choose.</span></div>':`<div class="sober-badge"><strong>${days.toLocaleString()} day${days===1?'':'s'}</strong><span>since your recorded recovery date</span></div>`;const milestones=recoveryMilestones.map(m=>{const ok=days!==null&&days>=m.days;return `<div class="milestone-card ${ok?'earned':'locked'}"><div class="milestone-medal">${ok?'★':'○'}</div><div><strong>${m.label}</strong><span>${ok?'Milestone reached':'Not reached yet'}</span></div>${ok?`<a class="btn secondary" href="#certificate/${m.days}">Certificate</a>`:''}</div>`}).join('');return shell(`${head('Recovery Progress','Your progress stays with you.','Your recovery date, sober-day count and milestones are stored separately from daily journal history, so clearing old entries does not reset your progress.')}<div class="recovery-grid"><section class="card recovery-summary">${badge}<div class="field"><label for="recoveryName">Name for certificates (optional)</label><input id="recoveryName" data-path="recovery.displayName" value="${esc(r.displayName||'')}" autocomplete="name"></div><div class="field"><label for="recoveryStartDate">Recovery / sober date</label><input id="recoveryStartDate" data-path="recovery.startDate" type="date" max="${todayISO()}" value="${esc(r.startDate||'')}"></div><p class="small-note">Quiet Strength calculates the counter from the date you enter. It does not independently verify sobriety and will never guess a relapse from your private writing.</p>${days!==null&&next?`<div class="notice"><strong>Next milestone:</strong> ${next.label} in ${next.days-days} day${next.days-days===1?'':'s'}.</div>`:days!==null?'<div class="notice"><strong>Milestones:</strong> every milestone currently built into Quiet Strength has been reached.</div>':''}<div class="toolbar"><button class="btn danger" id="resetRecoveryProgressBtn" type="button">Reset recovery date & milestones</button></div></section><section class="card"><h3>What QSR remembers</h3><div class="progress-stats"><div><strong>${days===null?'—':days.toLocaleString()}</strong><span>recovery days</span></div><div><strong>${checkins}</strong><span>daily check-ins stored</span></div><div><strong>${completed}</strong><span>completed daily outputs</span></div><div><strong>${tools}</strong><span>different tools used</span></div></div><p class="card-copy">Approximate encrypted workbook content before encryption overhead: <strong>${formatStorageBytes(storedStateSize())}</strong>.</p><div class="toolbar"><a class="btn secondary" href="#history">View all saved days</a><a class="btn secondary" href="#settings">Privacy & backup</a></div></section></div><h2 class="section-title">Milestone badges</h2><div class="milestone-grid">${milestones}</div><section class="card storage-cleanup"><h3>Manage phone storage without losing recovery progress</h3><p class="card-copy">These options remove daily check-ins, daily outputs and daily tool-use history only. Your recovery date, sober-day counter, milestone badges, workbook answers, settings and passcode stay in place.</p><div class="toolbar"><button class="btn secondary" data-cleanup-days="90" type="button">Delete daily history older than 90 days</button><button class="btn secondary" data-cleanup-days="365" type="button">Delete daily history older than 1 year</button><button class="btn danger" id="clearAllDailyHistoryBtn" type="button">Delete all daily history</button></div><div class="notice"><strong>Before deleting:</strong> use Export full backup in Settings if the person may want those old entries later. Deleting daily history cannot be undone unless there is a backup.</div></section>`) }
  function certificate(){const total=recoveryDays(),requested=Number((location.hash||'').split('/')[1]),earned=total===null?[]:recoveryMilestones.filter(m=>total>=m.days),chosen=earned.find(m=>m.days===requested)||earned[earned.length-1];if(!chosen)return shell(`${head('Milestone Certificate','No certificate is available yet.','Set a recovery date and reach a milestone first.')}<div class="toolbar"><a class="btn" href="#recovery">Back to recovery progress</a></div>`);const name=esc(state.recovery?.displayName||'This person'),start=esc(state.recovery?.startDate||'');return shell(`<div class="certificate-actions toolbar"><a class="btn secondary" href="#recovery">Back to progress</a><button class="btn gold" id="printCertificateBtn" type="button">Print / save certificate</button></div><article class="certificate-page"><div class="certificate-mark">QS</div><div class="eyebrow">Quiet Strength Recovery</div><h1>Recovery Milestone Certificate</h1><p class="certificate-lead">This personal milestone recognises</p><div class="certificate-name">${name}</div><p class="certificate-lead">for reaching</p><div class="certificate-milestone">${esc(chosen.label)}</div><p class="certificate-days">${chosen.days.toLocaleString()} days of recorded recovery / sobriety</p><p>Recovery date recorded in Quiet Strength: <strong>${start}</strong></p><div class="certificate-seal">★</div><p class="certificate-note">A personal recovery milestone generated from the date entered by the user. It is not clinical, legal or treatment-provider verification.</p></article>`) }
  function settings(){const mins=authMinutes();return shell(`${head('Privacy, Passcode, Storage & Accessibility','Your writing belongs to you.','Version 1.9 stays local-first. Quiet Strength is protected by a device passcode and your entries remain on this device unless you deliberately export them.')}<div class="page-grid"><div class="card"><h3>Passcode lock <span class="tag">ON</span></h3><p class="card-copy">Your passcode is stored as a one-way cryptographic verifier, not as readable digits. Quiet Strength locks automatically after inactivity.</p><div class="field"><label for="autoLockSelect">Auto-lock after</label><select id="autoLockSelect"><option value="1" ${mins===1?'selected':''}>1 minute</option><option value="5" ${mins===5?'selected':''}>5 minutes</option><option value="15" ${mins===15?'selected':''}>15 minutes</option><option value="30" ${mins===30?'selected':''}>30 minutes</option><option value="60" ${mins===60?'selected':''}>1 hour</option></select></div><div class="toolbar"><button class="btn" id="lockSettingsBtn" type="button">Lock now</button></div><div class="divider"></div><h3>Change passcode</h3><div class="field"><label for="currentPin">Current passcode</label><input id="currentPin" type="password" inputmode="numeric" maxlength="8" autocomplete="current-password"></div><div class="field"><label for="newPin">New passcode</label><input id="newPin" type="password" inputmode="numeric" minlength="6" maxlength="8" autocomplete="new-password"></div><div class="field"><label for="confirmNewPin">Confirm new passcode</label><input id="confirmNewPin" type="password" inputmode="numeric" minlength="6" maxlength="8" autocomplete="new-password"></div><button class="btn secondary" id="changePasscodeBtn" type="button">Change passcode</button><p class="auth-error" id="passcodeSettingsMessage" role="alert" aria-live="polite"></p><div class="notice"><strong>Passcode encryption:</strong> your passcode is used to unlock the encrypted workbook on this device. Six or more digits is strongly recommended. Keep Windows/phone sign-in and device encryption enabled as an extra layer.</div></div><div class="card"><h3>Private device mode <span class="tag">ON</span></h3><p class="card-copy">No account is required. No cloud sync is connected in this build. Workbook entries are encrypted locally. Full backups are encrypted and require the passcode that protected the workbook when the backup was created.</p><div class="toolbar"><button class="btn" id="exportBtn">Export full backup</button><button class="btn secondary" id="importBackupBtn" type="button">Import backup</button><input id="importFile" type="file" accept=".qsrbackup,application/json" hidden><button class="btn secondary" id="persistStorageBtn">Protect local storage</button><button class="btn secondary" id="installBtn" style="display:none">Install Quiet Strength Recovery</button><a class="btn secondary" href="#recovery">Recovery progress</a><a class="btn secondary" href="#privacy">Privacy explained</a><button class="btn danger" id="eraseBtn">Erase local data</button></div><div class="notice" id="storageNote"><strong>Encrypted full backup:</strong> completed daily outputs are included. Individual text/PDF exports are readable files, so store those privately.</div></div><div class="card"><h3>Accessibility</h3><p class="card-copy">Change the reading experience without changing your workbook content.</p><div class="field"><label>Text size</label><div class="chip-row"><button class="chip ${state.settings.textSize==='normal'?'active':''}" data-text-size="normal">Standard</button><button class="chip ${state.settings.textSize==='large'?'active':''}" data-text-size="large">Large</button><button class="chip ${state.settings.textSize==='xlarge'?'active':''}" data-text-size="xlarge">Extra large</button></div></div><label class="choice ${state.settings.highContrast?'checked':''}"><input type="checkbox" id="highContrastToggle" ${state.settings.highContrast?'checked':''}>Higher contrast</label></div></div>`) }

  function privacy(){
    return shell(`${head('Privacy & Device Storage','Your writing belongs to you.','This page explains what Quiet Strength does and does not do with your workbook data in this client version.')}
      <div class="page-grid">
        <div class="card"><h3>Free, optional recovery guide</h3><p class="card-copy">Quiet Strength Recovery is a self-guided recovery guide based on lived experience. The guide, workbook-style pages and tools are free. There is no account, subscription or paid feature.</p></div>
        <div class="card"><h3>No Quiet Strength account</h3><p class="card-copy">You do not sign in to a Quiet Strength server. This version has no cloud sync or remote workbook database.</p></div>
        <div class="card"><h3>Encrypted on this device</h3><p class="card-copy">Workbook entries, daily outputs and settings are encrypted before they are stored in this browser/app on this device. They are not intentionally uploaded to Quiet Strength when you type.</p></div>
        <div class="card"><h3>Recovery progress and cleanup</h3><p class="card-copy">Your recovery date and milestone progress are stored in the encrypted workbook state. You can delete old daily history to free local storage without resetting that recovery progress. A full local-data erase removes the recovery profile as well.</p></div>
        <div class="card"><h3>What the passcode does</h3><p class="card-copy">The passcode is used to derive the encryption key that unlocks your workbook. Quiet Strength stores a one-way verifier, not your readable passcode. A short passcode is easier to guess, so six or more digits is strongly recommended.</p></div>
        <div class="card"><h3>Backups matter</h3><p class="card-copy">If site/app data is cleared, the device is lost, or a forgotten passcode is reset by erasing local data, entries can be lost. Use <strong>Export full backup</strong> in Settings if you want a copy you control. New full backups are encrypted and require the passcode that protected the workbook when that backup was created. Individual text/PDF exports remain readable files.</p></div>
        <div class="card"><h3>Offline use</h3><p class="card-copy">After the first successful online load, Quiet Strength caches the workbook files for offline use. A browser or operating system can still remove cached data in some circumstances.</p></div>
        <div class="card"><h3>Disclaimer</h3><p class="card-copy">Quiet Strength Recovery is a peer-support and educational recovery guide created from lived experience. It is not a medical device and does not diagnose, treat, cure or prevent any medical condition or mental health disorder. The information and tools provided are not a substitute for professional medical advice, clinical therapy or emergency medical intervention. Always consult a qualified healthcare professional for medical advice, diagnosis or treatment. If you or someone else is in immediate danger or crisis, contact local emergency services or a crisis helpline.</p></div>
      </div>
      <div class="toolbar"><a class="btn" href="#settings">Privacy & storage settings</a><a class="btn secondary" href="#home">Back home</a></div>`);
  }

  function trackRecent(r){if(!interactiveIds.includes(r))return;const arr=state.meta.recentTools||[];state.meta.recentTools=[r,...arr.filter(x=>x!==r)].slice(0,8);state.meta.lastOpened=r;const date=todayISO();state.dailyUsage[date]??=[];if(!state.dailyUsage[date].includes(r))state.dailyUsage[date].push(r);persist()}
  function bind(){
    updateStatus();
    armAutoLock();
    const lockTop=document.querySelector('#lockNowBtn');if(lockTop)lockTop.addEventListener('click',()=>lockApp(false));
    const lockSettings=document.querySelector('#lockSettingsBtn');if(lockSettings)lockSettings.addEventListener('click',()=>lockApp(false));
    const autoLock=document.querySelector('#autoLockSelect');if(autoLock)autoLock.addEventListener('change',e=>{authMeta.autolockMinutes=Number(e.target.value)||5;saveAuth();armAutoLock();const m=document.querySelector('#passcodeSettingsMessage');if(m)m.textContent=`Auto-lock set to ${authMinutes()} minute${authMinutes()===1?'':'s'}.`;});
    const changePin=document.querySelector('#changePasscodeBtn');if(changePin)changePin.addEventListener('click',async()=>{const m=document.querySelector('#passcodeSettingsMessage'),current=document.querySelector('#currentPin').value,next=document.querySelector('#newPin').value,confirmPin=document.querySelector('#confirmNewPin').value;m.textContent='';if(next!==confirmPin){m.textContent='The new passcodes do not match.';return}try{await verifyPasscode(current);const mins=authMinutes();await createOrChangePasscode(next,mins);document.querySelector('#currentPin').value='';document.querySelector('#newPin').value='';document.querySelector('#confirmNewPin').value='';m.textContent='Passcode changed successfully.';}catch(err){m.textContent=err.message||'Passcode could not be changed.';}});
    document.querySelectorAll('[data-path]').forEach(el=>el.addEventListener('input',e=>{setPath(e.target.dataset.path,e.target.value);if(e.target.dataset.path.endsWith('.date')&&view()==='daily'&&e.target.value)location.hash='#daily/'+e.target.value}));
    document.querySelectorAll('[data-checkpath]').forEach(el=>el.addEventListener('change',e=>{const p=e.target.dataset.checkpath,k=e.target.dataset.checkkey;const o=getPath(p)||{};o[k]=e.target.checked;setPath(p,o);e.target.closest('.choice')?.classList.toggle('checked',e.target.checked)}));
    document.querySelectorAll('[data-chip-path]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();const p=e.currentTarget.dataset.chipPath,k=e.currentTarget.dataset.chipKey;const o=getPath(p)||{};o[k]=!o[k];setPath(p,o);e.currentTarget.classList.toggle('active',o[k])}));
    document.querySelectorAll('[data-feeling]').forEach(btn=>btn.addEventListener('click',e=>{state.feelings.primary=e.currentTarget.dataset.feeling;state.feelings.secondary='';persist();render()}));
    document.querySelectorAll('[data-subfeeling]').forEach(btn=>btn.addEventListener('click',e=>{state.feelings.secondary=e.currentTarget.dataset.subfeeling;persist();render()}));
    document.querySelectorAll('[data-balance]').forEach(sl=>sl.addEventListener('input',e=>{const k=e.target.dataset.balance,v=Number(e.target.value);state.balance[k]=v;document.querySelector('#num-'+k).textContent=v;queueSave();requestAnimationFrame(()=>{const holder=document.querySelector('.wheel-wrap');if(holder)holder.innerHTML=wheelSvg(state.balance,{recovery:'Recovery',sleep:'Sleep',work:'Work / Purpose',family:'Family',health:'Health',connection:'Connection',service:'Service',enjoyment:'Enjoyment'})})}));
    const ex=document.querySelector('#exportBtn');if(ex)ex.addEventListener('click',async()=>{try{await flushPendingSave();const pack=await createEncryptedBackupPackage();const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='quiet-strength-recovery-backup.qsrbackup';a.click();setTimeout(()=>URL.revokeObjectURL(url),0)}catch{alert('The encrypted backup could not be created. Make sure the workbook is unlocked and try again.')}});
    const imp=document.querySelector('#importFile');const importBtn=document.querySelector('#importBackupBtn');if(importBtn&&imp)importBtn.addEventListener('click',()=>{filePickerActive=true;imp.click()});if(imp)imp.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f){filePickerActive=false;armAutoLock();return;}const previous=state;try{if(f.size>20*1024*1024)throw new Error('large backup');const parsed=JSON.parse(await f.text());let restored;if(isEncryptedBackupPackage(parsed)){const pin=await requestBackupPasscode();if(pin===null)return;restored=await decryptEncryptedBackupPackage(parsed,pin)}else if(validBackup(parsed)){restored=deepMerge(clone(defaults),parsed)}else throw new Error('invalid backup');state=deepMerge(clone(defaults),restored);if(!await persist())throw new Error('save failed');alert(isEncryptedBackupPackage(parsed)?'Your encrypted backup was imported and secured on this device.':'Your older backup was imported and is now stored encrypted on this device.');render()}catch(err){state=previous;alert(err?.message==='Incorrect backup passcode.'?'That backup passcode is incorrect. Your current workbook is still open.':'This backup could not be imported. Check that it is a Quiet Strength backup under 20 MB. Your current workbook is still open.')}finally{filePickerActive=false;armAutoLock();e.target.value=''}});if(imp)imp.addEventListener('cancel',()=>{filePickerActive=false;armAutoLock()});
    const er=document.querySelector('#eraseBtn');if(er)er.addEventListener('click',async()=>{if(confirm('Erase all Quiet Strength entries and remove the passcode from this device?')){clearTimeout(saveTimer);await idbWriteQueue;if(!await idbClear()){alert('The device could not finish erasing stored data. Please try again before giving this device to anyone else.');return}try{localStorage.removeItem(KEY);localStorage.removeItem(OLD_KEY);localStorage.removeItem(SECURE_KEY);localStorage.removeItem(AUTH_KEY)}catch{alert('The device could not finish erasing stored data. Please try again before giving this device to anyone else.');return}try{sessionStorage.removeItem(AUTH_SESSION_KEY)}catch{}authMeta=null;dataKey=null;isUnlocked=false;state=clone(defaults);render();alert('Quiet Strength encrypted data and passcode have been erased from this device.')}});
    const ins=document.querySelector('#installBtn');if(ins&&window._qsInstallPrompt){ins.style.display='inline-block';ins.addEventListener('click',async()=>{window._qsInstallPrompt.prompt();await window._qsInstallPrompt.userChoice;window._qsInstallPrompt=null;ins.style.display='none'})}
    const clientIns=document.querySelector('#clientInstallBtn');if(clientIns&&window._qsInstallPrompt){clientIns.disabled=false;clientIns.addEventListener('click',async()=>{window._qsInstallPrompt.prompt();await window._qsInstallPrompt.userChoice;window._qsInstallPrompt=null;render()})}
    document.querySelectorAll('[data-complete-day]').forEach(b=>b.addEventListener('click',e=>completeDay(e.currentTarget.dataset.completeDay)));
    document.querySelectorAll('[data-download-day]').forEach(b=>b.addEventListener('click',e=>{const date=e.currentTarget.dataset.downloadDay,out=latestOutput(date);if(!out)return;const blob=new Blob([dayText(date,out)],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`quiet-strength-${date}.txt`;a.click();URL.revokeObjectURL(a.href)}));
    const printDay=document.querySelector('#printDayBtn');if(printDay)printDay.addEventListener('click',()=>window.print());
    const search=document.querySelector('#historySearch');if(search)search.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('#historyList .history-card').forEach(card=>card.style.display=!q||card.dataset.search.includes(q)?'grid':'none')});
    const dlArchive=document.querySelector('#downloadArchiveBtn');if(dlArchive)dlArchive.addEventListener('click',()=>{const dates=Object.keys(state.dailyOutputs||{}).sort();if(!dates.length){alert('No completed daily outputs yet.');return}const txt=dates.map(d=>dayText(d,latestOutput(d))).join('\n\n========================================\n\n');const blob=new Blob([txt],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='quiet-strength-daily-archive.txt';a.click();URL.revokeObjectURL(a.href)});
    const recoveryDate=document.querySelector('#recoveryStartDate');if(recoveryDate)recoveryDate.addEventListener('change',async e=>{const v=e.target.value;if(v&&(!isISODate(v)||v>todayISO())){alert('Choose today or an earlier recovery date.');state.recovery.startDate='';await persist();render();return}state.recovery.startDate=v;await persist();render()});
    document.querySelectorAll('[data-cleanup-days]').forEach(b=>b.addEventListener('click',async e=>{const days=Number(e.currentTarget.dataset.cleanupDays);if(!confirm(`Delete daily history older than ${days} days? Your recovery date, sober-day count and milestones will stay.`))return;const removed=deleteDailyHistoryOlderThan(days);await persist();alert(`${removed} dated record${removed===1?'':'s'} removed. Recovery progress was kept.`);render()}));
    const clearDaily=document.querySelector('#clearAllDailyHistoryBtn');if(clearDaily)clearDaily.addEventListener('click',async()=>{if(!confirm('Delete ALL daily check-ins, outputs and daily tool-use history from this device? Recovery progress and workbook answers will stay.'))return;if(!confirm('Final check: old daily history cannot be recovered without a backup. Continue?'))return;const removed=deleteAllDailyHistory();await persist();alert(`${removed} dated record${removed===1?'':'s'} removed. Recovery progress was kept.`);render()});
    const resetRecovery=document.querySelector('#resetRecoveryProgressBtn');if(resetRecovery)resetRecovery.addEventListener('click',async()=>{if(!confirm('Reset the recovery date and milestone badges? This does NOT delete journal history.'))return;state.recovery.startDate='';await persist();render()});
    const printCertificate=document.querySelector('#printCertificateBtn');if(printCertificate)printCertificate.addEventListener('click',()=>window.print());
    document.querySelectorAll('[data-text-size]').forEach(b=>b.addEventListener('click',e=>{state.settings.textSize=e.currentTarget.dataset.textSize;persist();applyAccessibility();render()}));
    const hc=document.querySelector('#highContrastToggle');if(hc)hc.addEventListener('change',e=>{state.settings.highContrast=e.target.checked;persist();applyAccessibility();render()});
    const ps=document.querySelector('#persistStorageBtn');if(ps)ps.addEventListener('click',async()=>{const note=document.querySelector('#storageNote');if(navigator.storage?.persist){const ok=await navigator.storage.persist();note.innerHTML=ok?'<strong>Local storage protected:</strong> this browser agreed to treat Quiet Strength data as persistent.':'<strong>Storage request completed:</strong> this browser did not grant persistent storage, so keep regular backups.'}else note.innerHTML='<strong>Storage protection:</strong> this browser does not expose that option. Keep regular backups.'});
  }

  const views={home,workbook,booklet,welcome,person,philosophy,closing,daily,history,day:dayOutput,brave,urges,feelings,moment,consequences,rhythm,fear,perspective,familyPatterns,familyRoles,childhoodRules,innerCritic,boundaries,resentment,accountability,apologies,connection,working,rebuilding,grounding,values,balance,support,warning,tools,help,recovery,certificate,settings,privacy};
  function render(){const root=document.querySelector('#app');if(!root)return;try{applyAccessibility();const r=view();if(r==='urgent'){root.innerHTML=urgentScreen();return}if(!authMeta){root.innerHTML=r==='privacy'?preAuthPrivacyScreen():passcodeSetupScreen();bindAuth();return}if(!isUnlocked){root.innerHTML=lockScreen();bindAuth();return}trackRecent(r);root.innerHTML=(views[r]||home)();bind();window.scrollTo({top:0,behavior:'instant'})}catch{root.innerHTML='<main class="urgent-screen"><div class="urgent-screen-card"><h1>This page could not be opened</h1><p>Your entries have not been erased. Please try the home page. If you need help right now, open the support page.</p><p><a class="btn" href="#home">Go to home</a> <a class="btn emergency-btn" href="#urgent">Support now</a></p></div></main>'}}
  function showPrivacyCover(){
    if(document.getElementById('privacyCover'))return;
    const cover=document.createElement('div');cover.id='privacyCover';cover.className='privacy-cover';
    cover.setAttribute('aria-hidden','true');
    cover.innerHTML='<div class="privacy-cover-mark"><img src="assets/icon.svg" alt=""><span>Private</span></div>';
    document.documentElement.classList.add('privacy-obscured');document.body.appendChild(cover);
  }
  function hidePrivacyCover(){document.getElementById('privacyCover')?.remove();document.documentElement.classList.remove('privacy-obscured')}
  async function flushPendingSave(){if(saveTimer){clearTimeout(saveTimer);saveTimer=null;await persist()}else await idbWriteQueue}
  ['pointerdown','keydown','touchstart'].forEach(evt=>window.addEventListener(evt,()=>{if(isUnlocked)armAutoLock()},{passive:true}));
  window.addEventListener('focus',()=>{if(document.visibilityState==='visible'){hidePrivacyCover();if(filePickerActive)setTimeout(()=>{if(filePickerActive){filePickerActive=false;armAutoLock()}},1200);if(authMeta&&!isUnlocked)render()}});
  window.addEventListener('pagehide',flushPendingSave);
  document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='hidden'){showPrivacyCover();try{await flushPendingSave()}catch{}if(authMeta&&isUnlocked&&!filePickerActive){dataKey=null;isUnlocked=false;try{sessionStorage.removeItem(AUTH_SESSION_KEY)}catch{}clearTimeout(inactivityTimer)}}else{hidePrivacyCover();if(authMeta&&!isUnlocked)render()}});
  window.addEventListener('hashchange',render);window.addEventListener('online',updateStatus);window.addEventListener('offline',updateStatus);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window._qsInstallPrompt=e;const b=document.querySelector('#installBtn');if(b)b.style.display='inline-block'});render();if(!authMeta)idbLoad().then(saved=>{if(validBackup(saved)&&String(saved.meta?.savedAt||'')>String(state.meta?.savedAt||'')){state=deepMerge(clone(defaults),saved);render()}});
  if('serviceWorker' in navigator && location.protocol.startsWith('http')) window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
})();